      {/* BOTTOM LEFT CLUSTER - Navigation & Chords */}
      <button className={`absolute rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold backdrop-blur hover:bg-yellow-600/40 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('center'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'center', onCenter)} title="Center Display"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /></svg></button>

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-blue-500 font-bold backdrop-blur hover:bg-blue-600/40 active:bg-blue-600 active:text-white transition-all shadow-[0_0_15px_rgba(59,130,246,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('depth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'depth', onIncreaseDepth)} title="Increase Depth from Selection"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>)}

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('decreaseDepth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'decreaseDepth', onDecreaseDepth)} title="Decrease Depth"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 12h-15" /></svg></button>)}

      <div className={`absolute flex items-center gap-2 z-[150] transition-all ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50 rounded-lg p-1 border-dashed border-2 border-yellow-500/50' : ''}`} style={{ ...draggableStyle('chords') }} onPointerDown={(e) => handleDrag(e, 'chords')}>
          <button className="rounded bg-indigo-600/20 border-2 border-indigo-500 flex items-center justify-center text-indigo-500 font-bold backdrop-blur hover:bg-indigo-600/40 active:bg-indigo-600 active:text-white transition-all shadow-[0_0_15px_rgba(99,102,241,0.4)] select-none" style={{ width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'chords', onAddChord)} title="Store Current Chord"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>

          {!uiUnlocked && savedChords.filter(c => c.visible).map((chord, i) => {
              const isActive = activeChordIds.includes(chord.id);
              return (
                  <div key={chord.id} className="flex flex-col items-center gap-1 group">
                      <button 
                        className={`rounded border-2 flex items-center justify-center font-bold backdrop-blur transition-all shadow-lg select-none ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-[0_0_15px_rgba(99,102,241,0.8)] scale-110' : 'bg-slate-800/60 border-slate-600 text-slate-400 hover:border-indigo-500 hover:text-indigo-400'}`} 
                        style={{ width: chordSize, height: chordSize, fontSize: 14 * uiScale }} 
                        onPointerDown={(e) => { e.stopPropagation(); toggleChord(chord.id); }} 
                        onContextMenu={(e) => { e.preventDefault(); e.stopPropagation(); if(onRemoveChord) onRemoveChord(chord.id); }}
                      >
                          {chord.label}
                      </button>
                      <button
                          className="text-slate-600 hover:text-red-400 transition-colors p-1 opacity-60 hover:opacity-100"
                          onPointerDown={(e) => { e.stopPropagation(); if(onRemoveChord) onRemoveChord(chord.id); }}
                          title="Delete Chord"
                      >
                          <svg xmlns="http://www.w3.org/2000/svg" className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                              <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                          </svg>
                      </button>
                  </div>
              );
          })}
      </div>
    </>
  );
};

export default FloatingControls;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  // removed currentX/Y from state to prevent re-renders on every move
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Cache the bounding rect to avoid reflows
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Unified Scale Calculation
  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number>>(new Map());

  // Store timestamps for ripple effects [nodeId, timestamp]
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set(persistentLatches.values());
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches(prev => {
                  if (prev.has(nodeId)) {
                      const next = new Map(prev);
                      next.delete(nodeId);
                      return next;
                  }
                  return prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord && chord.soundConfig) {
              audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, { mode: number, presetId: string }>();

      persistentLatches.forEach((mode, nodeId) => {
          const pId = mode === 2 ? 'normal' : 'latch';
          effective.set(nodeId, { mode, presetId: pId });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            const hasConfig = !!chordDef.soundConfig;
            const pId = hasConfig ? `chord-${chordId}` : (latchMode === 2 ? 'normal' : 'latch');

            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) {
                    effective.set(n.id, { mode: defaultChordMode, presetId: pId });
                }
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, number>();
      audioLatchedNodes.forEach((val, key) => visual.set(key, val.mode));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;

          const isHybridMode = isSustainingInstrument && isSustainActive && isBendEnabled;
          if (isHybridMode) return;

          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  // Line Logic
  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) {
                active.push(line);
            }
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) {
                    dist += Math.abs(A.coords[k] - B.coords[k]);
                }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    const maxP = Math.max(A.maxPrime, B.maxPrime);
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: maxP, sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) {
                  resultLines.add(line);
              }
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  // Update Rect on Scroll/Resize
  const updateRect = () => {
      if (dynamicCanvasRef.current) {
          canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  // Imperative Handle
  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) {
            setPersistentLatches(new Map());
        } else {
            setPersistentLatches(prev => {
                const next = new Map();
                prev.forEach((val, key) => {
                    if (val !== mode) next.set(key, val);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        persistentLatches.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  // Handle Lattice Resize (Symmetric Expansion)
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  // Handle Zoom Stabilization (Keep center view point steady when zooming)
  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;
          const centerOffset = dynamicSizeRef.current / 2;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_1_1 = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_1_1 = (currentScrollTop + viewH / 2) - centerOffset;

          if (Math.abs(centerX_from_1_1) < 2.0 && Math.abs(centerY_from_1_1) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2;
              container.scrollTop = centerOffset - viewH / 2;
          } else {
              const normX = centerX_from_1_1 / oldSpacing;
              const normY = centerY_from_1_1 / oldSpacing;

              const newCenterX_from_1_1 = normX * newSpacing;
              const newCenterY_from_1_1 = normY * newSpacing;

              container.scrollLeft = (newCenterX_from_1_1 + centerOffset) - viewW / 2;
              container.scrollTop = (newCenterY_from_1_1 + centerOffset) - viewH / 2;
          }

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          skin: settings.activeSkin
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        const MAX_CANVAS_SIZE = 5000; 
        const clampedSize = Math.min(finalSize, MAX_CANVAS_SIZE);

        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(clampedSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }
      const padding = 600; 
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

      const MAX_CANVAS_SIZE = 5000;
      const clampedSize = Math.min(finalSize, MAX_CANVAS_SIZE);

      if (Math.abs(clampedSize - dynamicSize) > 50) setDynamicSize(clampedSize);
  }, [settings.buttonSpacingScale, effectiveScale]);

  // Audio Latched Nodes Sync
  const prevAudioLatchedRef = useRef<Map<string, { mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;

      current.forEach((data, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- HIT TEST LOGIC ---
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current;
      if (!rect) {
          rect = dynamicCanvasRef.current.getBoundingClientRect();
          canvasRectRef.current = rect;
      }

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const x = clientX - rect.left;
      const y = clientY - (rect.top + pixelOffset); 

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      // 1. Force Resume on Interaction
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      // 2. FORCE RECT UPDATE on interaction start to handle layout shifts/latency
      updateRect();

      // Pre-calculate relative canvas coordinates to avoid jitter in renderer
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect();
          // Normalize to canvas coordinate space (considering scroll)
          const bend = globalBendRef.current;
          const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

          canvasPos = {
              x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft,
              y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pixelOffset
          };
      }

      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode === 1 || latchMode === 2;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled;

        if (isSustainingInstrument && isSustainActive) {
             const existingMode = persistentLatches.get(hitNode.id);
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (existingMode === latchMode) next.delete(hitNode.id);
                 else next.set(hitNode.id, latchMode);
                 return next;
             });
        }

        if (isBendEnabled || !isSustainActive || latchMode === 3) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            // NOTE: startVoice now queues internally if context is suspended/initing
            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null
          };
          // Don't update state for empty space clicks unless needed, to save render? 
          // Actually we need the cursor for bending reference if dragging from empty space logic existed, but it doesn't.
          // Keeping it consistent.
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    // 1. Update coordinates in Ref ONLY (No React State Update here!)
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = {
            x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft,
            y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pixelOffset
        };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId);
    cursorPositionsRef.current.set(e.pointerId, canvasPos);

    // Check if we need to update hasMoved
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) {
        const dx = Math.abs(canvasPos.x - prevPos.x);
        const dy = Math.abs(canvasPos.y - prevPos.y);
        if (dx > 2 || dy > 2) hasMoved = true;
    }

    // 2. Logic Check (Hit Testing)
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode === 1 || latchMode === 2;
    const isSustainActive = isCurrentSustainEnabled;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled;

    const isBending = isBendEnabled && !!cursor.originNodeId;

    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2;
         const rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();

         const bend = globalBendRef.current;
         const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale; 

         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originScreenY = (rect.top + pixelOffset) + (originNode.y * spacing) + centerOffset;
             const currentDeltaY = e.clientY - originScreenY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    // Latch Dragging Logic (enter/exit)
    if (hitNode) {
         const isAlreadyLatched = isSustainingInstrument && isSustainActive && 
                                  persistentLatchesRef.current.get(hitNode.id) === latchMode;

         if (isSustainingInstrument && isSustainActive && isBendEnabled) {
             // Hybrid Mode Logic...
             const centerOffset = dynamicSizeRef.current / 2;
             const rect = canvasRectRef.current || dynamicCanvasRef.current!.getBoundingClientRect();
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const bend = globalBendRef.current;
             const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

             const hitNodeScreenY = (rect.top + pixelOffset) + (hitNode.y * spacing) + centerOffset;
             // We need previous screen Y. Approximate via prevPos
             // Note: prevPos is canvas relative.
             // This logic is getting complex for a pure ref update.
             // Simplifying: if entering node area, trigger latch.
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 if (!isAlreadyLatched) {
                     setPersistentLatches(prev => {
                         const next = new Map(prev);
                         next.set(hitNode.id, latchMode);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    // Node Entry/Exit Logic
    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             const isAlreadyLatched = isSustainingInstrument && isSustainActive && 
                                      persistentLatchesRef.current.get(hitNode.id) === latchMode;

             if (isSustainingInstrument && isSustainActive && !isBendEnabled) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    if (!isAlreadyLatched) { 
                        setPersistentLatches(prev => {
                            const next = new Map(prev);
                            next.set(hitNode.id, latchMode);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    // 3. Update State ONLY if logic changed (hover node change)
    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
            audioEngine.stopVoice(voiceId);
            if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
        }
        else if (cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(voiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
             }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const wrapper = wrapperRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (wrapper) {
          const bend = globalBendRef.current;
          const pixelOffset = -bend * (PITCH_SCALE / 12) * currentScale;
          const transform = `translate3d(0px, ${pixelOffset}px, 0px)`;
          wrapper.style.transform = transform;
      }

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current,
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              dynamicSize: dynamicSizeRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      if (isJIOverride) {
          return { ...baseStyle, backgroundColor: 'black', backgroundImage: 'none' };
      }

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { getRainbowPeriod, PITCH_SCALE } from './ProjectionService';

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, number>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    activeCursors: Map<number, any>;
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    dynamicSize: number;
    view: { x: number, y: number, w: number, h: number };
    time: number;
}

export class LatticeRenderer {
    // Cache keys to prevent unnecessary redraws
    private lastData: any = null;
    private lastSettingsSignature: string = '';
    private lastSize: number = 0;
    private lastScale: number = 0;

    // Track if BG lines need update (dependent on brightened/active lines mostly, but brightened lines modify BG appearance)
    private lastBrightenedLines: LatticeLine[] = [];

    public render(
        bgCanvas: HTMLCanvasElement, 
        staticCanvas: HTMLCanvasElement, 
        dynamicCanvas: HTMLCanvasElement, 
        state: RenderState
    ) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, 
            activeCursors, cursorPositions, nodeTriggerHistory, 
            globalBend, effectiveScale, dynamicSize, view, time 
        } = state;

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const staticCtx = staticCanvas.getContext('2d', { alpha: true });
        const activeCtx = dynamicCanvas.getContext('2d', { alpha: true });

        if (!bgCtx || !staticCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        let needsFullRedraw = false;

        // Sync canvas dimensions
        if (bgCanvas.width !== dynamicSize * dpr || bgCanvas.height !== dynamicSize * dpr) {
            [bgCanvas, staticCanvas, dynamicCanvas].forEach(c => {
                c.width = dynamicSize * dpr;
                c.height = dynamicSize * dpr;
            });
            bgCtx.scale(dpr, dpr);
            staticCtx.scale(dpr, dpr);
            activeCtx.scale(dpr, dpr);
            needsFullRedraw = true;
        } else {
            // Ensure transform is reset if we don't resize, to prevent drift or accumulation
            bgCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
            staticCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
            activeCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }

        const settingsSig = JSON.stringify({
            spacing: settings.buttonSpacingScale,
            size: settings.buttonSizeScale,
            colors: settings.colors,
            layout: settings.layoutApproach,
            vis: settings.limitVisuals,
            shape: settings.buttonShape,
            text: settings.nodeTextSizeScale,
            fraction: settings.showFractionBar,
            width: settings.baseLineWidth,
            bright: settings.lineBrighteningWidth
        });

        // Determine if static layers need update
        const staticDirty = needsFullRedraw || 
                            data !== this.lastData || 
                            settingsSig !== this.lastSettingsSignature ||
                            effectiveScale !== this.lastScale ||
                            dynamicSize !== this.lastSize;

        // Determine if background lines need update (e.g. line brightening on hover)
        const bgDirty = staticDirty || brightenedLines !== this.lastBrightenedLines;

        if (staticDirty) {
            this.lastData = data;
            this.lastSettingsSignature = settingsSig;
            this.lastScale = effectiveScale;
            this.lastSize = dynamicSize;
        }

        if (bgDirty) {
            this.lastBrightenedLines = brightenedLines;
        }

        // View Culling Calculation
        const pixelOffset = -globalBend * (PITCH_SCALE / 12) * effectiveScale;
        const viewPad = 300; 
        const leftBound = view.x - viewPad;
        const rightBound = view.x + view.w + viewPad;
        const topBound = view.y - viewPad - pixelOffset; 
        const bottomBound = view.y + view.h + viewPad - pixelOffset;

        const centerOffset = dynamicSize / 2;
        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = settings.colors;
        const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

        // --- 1. RENDER BACKGROUND LINES (Cached) ---
        if (bgDirty) {
            bgCtx.clearRect(0, 0, dynamicSize, dynamicSize);
            bgCtx.lineCap = 'round';

            const baseWidth = settings.baseLineWidth || 1.0;
            const linesByLimit: Record<number, number[]> = {};

            // Group lines by limit for batch drawing
            for (const line of data.lines) {
                if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
                const arr = linesByLimit[line.limit];
                arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
            }

            for (const limitStr in linesByLimit) {
                const limit = parseInt(limitStr);
                const coords = linesByLimit[limit];
                const color = isJIOverride ? '#fff' : (colorCache[limit] || '#666');

                bgCtx.beginPath();
                for(let i=0; i<coords.length; i+=4) {
                    // Culling for initial draw
                    if (Math.max(coords[i], coords[i+2]) < 0 || Math.min(coords[i], coords[i+2]) > dynamicSize || 
                        Math.max(coords[i+1], coords[i+3]) < 0 || Math.min(coords[i+1], coords[i+3]) > dynamicSize) continue;

                    bgCtx.moveTo(coords[i], coords[i+1]);
                    bgCtx.lineTo(coords[i+2], coords[i+3]);
                }
                bgCtx.lineWidth = (limit === 1 ? Math.max(2.5, baseWidth * 2.5) : baseWidth) * effectiveScale; 
                bgCtx.strokeStyle = color;
                bgCtx.globalAlpha = (isJIOverride ? 0.15 : 0.3); 

                if (limit === 1) bgCtx.setLineDash([5 * effectiveScale, 5 * effectiveScale]);
                else bgCtx.setLineDash([]);
                bgCtx.stroke();
            }
            bgCtx.setLineDash([]); 

            // Brightened Lines (Voice Leading Hints)
            if (brightenedLines.length > 0) {
                const brightWidth = settings.lineBrighteningWidth || 1.0;
                for (const line of brightenedLines) {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;

                    const limitColor = isJIOverride ? '#fff' : (colorCache[line.limit] || '#666');
                    bgCtx.beginPath();
                    bgCtx.moveTo(x1, y1);
                    bgCtx.lineTo(x2, y2);
                    bgCtx.lineWidth = brightWidth * effectiveScale;
                    bgCtx.strokeStyle = limitColor;
                    bgCtx.globalAlpha = isJIOverride ? 0.4 : 0.8; 
                    bgCtx.stroke();
                }
            }
        }

        // --- 2. RENDER STATIC NODES (Cached) ---
        if (staticDirty) {
            staticCtx.clearRect(0, 0, dynamicSize, dynamicSize);
            for (const node of data.nodes) {
                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset;

                // Aggressive culling not needed for static if cached, but good practice
                // Note: Static canvas needs full content for scrolling if we don't redraw on scroll
                // But current architecture uses native scroll on container, so we MUST draw everything.

                const cTop = isJIOverride ? '#fff' : (colorCache[node.limitTop] || '#666');
                const cBottom = isJIOverride ? '#eee' : (colorCache[node.limitBottom] || '#666');

                const radius = baseRadius; 

                staticCtx.globalAlpha = 1.0;
                staticCtx.beginPath();
                if (isDiamond) {
                    staticCtx.moveTo(x, y - radius);
                    staticCtx.lineTo(x + radius, y);
                    staticCtx.lineTo(x, y + radius);
                    staticCtx.lineTo(x - radius, y);
                } else {
                    staticCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                staticCtx.closePath();

                if (isJIOverride) {
                    staticCtx.fillStyle = '#111';
                    staticCtx.fill();
                    staticCtx.lineWidth = 2 * effectiveScale;
                    staticCtx.strokeStyle = '#fff';
                    staticCtx.stroke();
                } else {
                    const grad = staticCtx.createLinearGradient(x, y - radius, x, y + radius);
                    grad.addColorStop(0.45, cTop);
                    grad.addColorStop(0.55, cBottom);
                    staticCtx.fillStyle = grad;
                    staticCtx.fill();
                }

                const combinedScale = settings.buttonSizeScale; 
                if (combinedScale > 0.4) {
                    staticCtx.fillStyle = isJIOverride ? '#fff' : 'white';
                    staticCtx.textAlign = 'center';
                    staticCtx.textBaseline = 'middle';
                    let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                    staticCtx.font = `bold ${fontSize}px sans-serif`; 

                    const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                    staticCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                    if (settings.showFractionBar) {
                        staticCtx.beginPath();
                        staticCtx.moveTo(x - (radius * 0.4), y);
                        staticCtx.lineTo(x + (radius * 0.4), y);
                        staticCtx.lineWidth = 1 * effectiveScale;
                        staticCtx.strokeStyle = isJIOverride ? 'rgba(255,255,255,0.4)' : `rgba(255,255,255,0.8)`;
                        staticCtx.stroke();
                    }
                    staticCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
                }
            }
        }

        // --- 3. RENDER ACTIVE OVERLAYS (Every Frame) ---
        // Clear Active Canvas (Consider Viewport Optimization)
        // Optimization: Clearing visible rect is safer for fill-rate, but clearing full canvas handles artifacts.
        // Given 25MP worst case, let's try to clear mostly what we see + margin
        // To be safe against fast scrolls, we clear slightly more.
        const clearX = Math.max(0, leftBound);
        const clearY = Math.max(0, topBound);
        const clearW = Math.min(dynamicSize, rightBound) - clearX;
        const clearH = Math.min(dynamicSize, bottomBound) - clearY;

        // Due to pitch bend offset, bottomBound might be larger than canvas.
        // Safe approach for dynamic: clear whole thing if small, or viewport if large.
        activeCtx.clearRect(0, 0, dynamicSize, dynamicSize);

        activeCtx.lineCap = 'round';

        // A. Active Lines (Currently sounding intervals)
        // Note: Active Lines animate, so they belong in dynamic loop or separate animated layer
        // Since we moved BG lines to cached canvas, active lines must be drawn on activeCtx or a separate layer.
        // Let's draw them on activeCtx for animation smoothness.
        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = isJIOverride ? '#fff' : (colorCache[line.limit] || '#666');

            // Solid base
            activeCtx.beginPath();
            activeCtx.moveTo(x1, y1);
            activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = (isJIOverride ? 2 : 4) * effectiveScale;
            activeCtx.strokeStyle = limitColor;
            activeCtx.globalAlpha = 1.0;
            activeCtx.stroke();

            // Animated flow
            if (settings.isVoiceLeadingAnimationEnabled) {
                const grad = activeCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, isJIOverride ? 'rgba(255,255,255,1.0)' : 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                activeCtx.beginPath();
                activeCtx.moveTo(x1, y1);
                activeCtx.lineTo(x2, y2);

                // Glow
                activeCtx.strokeStyle = grad;
                activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                activeCtx.globalAlpha = 0.3; 
                activeCtx.stroke();

                // Core
                activeCtx.lineWidth = 4 * effectiveScale;
                activeCtx.globalAlpha = 1.0;
                activeCtx.stroke();
            }
        }

        // B. Latched/Active Nodes
        for (const id of visualLatchedNodes.keys()) {
             const node = data.nodes.find(n => n.id === id); 
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = isJIOverride ? '#fff' : (colorCache[node.limitTop] || '#666');
             const zoomScale = settings.latchedZoomScale;
             const radius = baseRadius * zoomScale;

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius);
                activeCtx.lineTo(x + radius, y);
                activeCtx.lineTo(x, y + radius);
                activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isJIOverride) {
                 activeCtx.fillStyle = '#fff';
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, colorCache[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
             }
             activeCtx.fill();

             // Outline / Halo
             if (settings.isColoredIlluminationEnabled && !isJIOverride) {
                 const rp = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale);
                 const phase = (y % rp) / rp;
                 const hue = (settings.rainbowOffset + phase * 360) % 360;
                 const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                 activeCtx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 activeCtx.lineWidth = 4 * effectiveScale;
             } else {
                 activeCtx.strokeStyle = isJIOverride ? '#fff' : 'white';
                 activeCtx.lineWidth = isJIOverride ? 4 * effectiveScale : 3 * effectiveScale;
                 if (isJIOverride) {
                    activeCtx.shadowBlur = 10 * effectiveScale;
                    activeCtx.shadowColor = '#fff';
                 }
             }
             activeCtx.stroke();
             activeCtx.shadowBlur = 0; 

             // Text Label
             const combinedScale = settings.buttonSizeScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = isJIOverride ? '#000' : 'white';
                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (radius * 0.4), y);
                    activeCtx.lineTo(x + (radius * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale;
                    activeCtx.strokeStyle = isJIOverride ? 'rgba(0,0,0,0.5)' : 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // C. Trigger Ripples
        const now = Date.now();
        const rippleDuration = 500; 
        activeCtx.lineWidth = 2 * effectiveScale;
        activeCtx.strokeStyle = 'white';

        nodeTriggerHistory.forEach((timestamp, nodeId) => {
            const age = now - timestamp;
            if (age > rippleDuration) return;

            const node = data.nodes.find(n => n.id === nodeId);
            if (!node) return;

            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) return;

            const progress = age / rippleDuration;
            const eased = 1 - Math.pow(1 - progress, 3);
            const rippleRadius = baseRadius * (1 + eased * 1.5);
            const opacity = 1.0 - progress;

            activeCtx.beginPath();
            activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
            activeCtx.globalAlpha = opacity;
            activeCtx.stroke();
        });
        activeCtx.globalAlpha = 1.0;

        // D. Pitch Bend Cursors
        if (settings.isPitchBendEnabled) {
            activeCursors.forEach(c => {
                if (c.originNodeId) {
                    const node = data.nodes.find(n => n.id === c.originNodeId);
                    if (node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;

                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         // Pos is already canvas-relative from component logic
                         const cx_rel = pos.x; 
                         const cy_rel = pos.y;

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx_rel, cy_rel);
                         activeCtx.strokeStyle = isJIOverride ? '#fff' : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

export const AUDIO_PROCESSOR_CODE = `
// --- 1. DSP UTILS & CONSTANTS ---

const TWO_PI = 2 * Math.PI;

// Reduced wavetable size for cache efficiency while maintaining good quality
const WAVETABLE_SIZE = 8192; 
const SINE_TABLE = new Float32Array(WAVETABLE_SIZE + 1);

for (let i = 0; i <= WAVETABLE_SIZE; i++) {
    SINE_TABLE[i] = Math.sin((i / WAVETABLE_SIZE) * TWO_PI);
}

const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none'
};

const DUMMY_PRESET_DATA = {
    osc1: DUMMY_OSC_CONFIG,
    osc2: DUMMY_OSC_CONFIG,
    osc3: DUMMY_OSC_CONFIG,
    modMatrix: [],
    gain: 1.0,
    spread: 0,
    stereoPanSpeed: 0,
    stereoPanDepth: 0
};

// --- 2. BASIC DSP CLASSES ---

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate) {
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.42));
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; 
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        {
            const index = this.phase * WAVETABLE_SIZE;
            const i = Math.floor(index);
            const f = index - i;
            sample = SINE_TABLE[i] + f * (SINE_TABLE[i + 1] - SINE_TABLE[i]);
        }
        break;
      case 'triangle':
        {
            let t = -1.0 + (2.0 * this.phase);
            sample = 2.0 * (Math.abs(t) - 0.5);
        }
        break;
      case 'sawtooth':
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
    }

    return sample;
  }
}

// --- 3. VOICE LOGIC ---

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal';
    this.mode = 'gate';
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0;
    this.pendingRelease = false;

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  updateSampleRate(newRate) {
      if (this.sampleRate === newRate) return;
      this.sampleRate = newRate;
      this.oscs.forEach(osc => { osc.sampleRate = newRate; osc.blep.sampleRate = newRate; });
  }

  trigger(id, freq, type, mode) {
    this.id = id;
    this.type = type || 'normal';
    this.mode = mode || 'gate';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0;
    this.pendingRelease = false;

    this.envs.forEach(env => env.trigger());
    this.filters.forEach(f => f.reset());
    this.lfoPhases.fill(0.0);
  }

  release() {
    if (currentTime - this.startTime < 0.01) {
        this.pendingRelease = true;
    } else {
        this.doRelease();
    }
  }

  doRelease() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.pendingRelease = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
  }

  renderBlock(preset, dt, bufL, bufR, len, panSpeed, panDepth, startPanPhase, globalBend) {
    if (!this.active) return;

    if (this.pendingRelease) {
        if (currentTime - this.startTime >= 0.01) {
            this.pendingRelease = false;
            this.doRelease();
        }
    }

    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
      this.baseFreq += diff * 0.005; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    const osc1 = preset.osc1 || DUMMY_OSC_CONFIG;
    const osc2 = preset.osc2 || DUMMY_OSC_CONFIG;
    const osc3 = preset.osc3 || DUMMY_OSC_CONFIG;
    const matrix = preset.modMatrix || [];
    const spreadAmount = preset.spread || 0;
    const voiceGain = preset.gain || 0.5;
    const hasMatrix = matrix.length > 0;

    let anyEnvActive = false;
    let panPhase = startPanPhase;

    const lfoRate1 = osc1.lfoRate || 0;
    const lfoRate2 = osc2.lfoRate || 0;
    const lfoRate3 = osc3.lfoRate || 0;

    let osc1StaticFreq = 0, osc2StaticFreq = 0, osc3StaticFreq = 0;
    let osc1ModPitch = false, osc2ModPitch = false, osc3ModPitch = false;

    if (osc1.enabled) {
        if (osc1.lfoTarget === 'pitch') osc1ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc1_pitch')) osc1ModPitch = true;
        if (!osc1ModPitch) {
            const cents = osc1.coarseDetune + osc1.fineDetune;
            osc1StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc2.enabled) {
        if (osc2.lfoTarget === 'pitch') osc2ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc2_pitch')) osc2ModPitch = true;
        if (!osc2ModPitch) {
            const cents = osc2.coarseDetune + osc2.fineDetune;
            osc2StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    if (osc3.enabled) {
        if (osc3.lfoTarget === 'pitch') osc3ModPitch = true;
        if (hasMatrix && matrix.some(r => r.enabled && r.target === 'osc3_pitch')) osc3ModPitch = true;
        if (!osc3ModPitch) {
            const cents = osc3.coarseDetune + osc3.fineDetune;
            osc3StaticFreq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
        }
    }

    for (let s = 0; s < len; s++) {
        anyEnvActive = false;

        const env1 = this.envs[0].process(osc1, dt);
        this.envVals[0] = env1;
        if (this.envs[0].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[0] += lfoRate1 * dt;
        if (this.lfoPhases[0] >= 1.0) this.lfoPhases[0] -= 1.0;
        this.lfoVals[0] = Math.sin(TWO_PI * this.lfoPhases[0]);

        const env2 = this.envs[1].process(osc2, dt);
        this.envVals[1] = env2;
        if (this.envs[1].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[1] += lfoRate2 * dt;
        if (this.lfoPhases[1] >= 1.0) this.lfoPhases[1] -= 1.0;
        this.lfoVals[1] = Math.sin(TWO_PI * this.lfoPhases[1]);

        const env3 = this.envs[2].process(osc3, dt);
        this.envVals[2] = env3;
        if (this.envs[2].stage !== 'idle') anyEnvActive = true;
        this.lfoPhases[2] += lfoRate3 * dt;
        if (this.lfoPhases[2] >= 1.0) this.lfoPhases[2] -= 1.0;
        this.lfoVals[2] = Math.sin(TWO_PI * this.lfoPhases[2]);

        if (!anyEnvActive && s === len - 1) {
            this.active = false;
        }

        let modP1=0, modC1=0, modG1=0, modR1=0;
        let modP2=0, modC2=0, modG2=0, modR2=0;
        let modP3=0, modC3=0, modG3=0, modR3=0;

        if (hasMatrix) {
            for(let m = 0; m < matrix.length; m++) {
                const row = matrix[m];
                if (!row.enabled) continue;
                let srcVal = 0;
                if (row.source === 'env1') srcVal = this.envVals[0];
                else if (row.source === 'env2') srcVal = this.envVals[1];
                else if (row.source === 'env3') srcVal = this.envVals[2];
                else if (row.source === 'lfo1') srcVal = this.lfoVals[0];
                else if (row.source === 'lfo2') srcVal = this.lfoVals[1];
                else if (row.source === 'lfo3') srcVal = this.lfoVals[2];

                const amt = srcVal * row.amount;

                switch(row.target) {
                    case 'osc1_pitch': modP1 += amt; break;
                    case 'osc1_cutoff': modC1 += amt; break;
                    case 'osc1_gain': modG1 += amt; break;
                    case 'osc1_res': modR1 += amt; break;
                    case 'osc2_pitch': modP2 += amt; break;
                    case 'osc2_cutoff': modC2 += amt; break;
                    case 'osc2_gain': modG2 += amt; break;
                    case 'osc2_res': modR2 += amt; break;
                    case 'osc3_pitch': modP3 += amt; break;
                    case 'osc3_cutoff': modC3 += amt; break;
                    case 'osc3_gain': modG3 += amt; break;
                    case 'osc3_res': modR3 += amt; break;
                }
            }
        }

        let voiceMix = 0.0;

        if (osc1.enabled && this.envVals[0] > 0.0001) {
            let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
            const d = osc1.lfoDepth || 0;
            const v = this.lfoVals[0];
            if (osc1.lfoTarget === 'pitch') hardPitch = v * d;
            else if (osc1.lfoTarget === 'filter') hardFilter = v * d * 20;
            else if (osc1.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

            let freq;
            if (osc1ModPitch) {
                const cents = osc1.coarseDetune + osc1.fineDetune + hardPitch + (modP1 * 1200);
                freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
            } else {
                freq = osc1StaticFreq;
            }

            let sig = this.oscs[0].process(freq, osc1.waveform, dt);

            const cut = osc1.filterCutoff + hardFilter + (modC1 * 5000);
            const res = Math.max(0, osc1.filterResonance + (modR1 * 10));
            sig = this.filters[0].process(sig, cut, res, this.sampleRate);

            voiceMix += sig * osc1.gain * this.envVals[0] * hardAmp * Math.max(0, 1.0 + modG1);
        }

        if (osc2.enabled && this.envVals[1] > 0.0001) {
            let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
            const d = osc2.lfoDepth || 0;
            const v = this.lfoVals[1];
            if (osc2.lfoTarget === 'pitch') hardPitch = v * d;
            else if (osc2.lfoTarget === 'filter') hardFilter = v * d * 20;
            else if (osc2.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

            let freq;
            if (osc2ModPitch) {
                const cents = osc2.coarseDetune + osc2.fineDetune + hardPitch + (modP2 * 1200);
                freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
            } else {
                freq = osc2StaticFreq;
            }

            let sig = this.oscs[1].process(freq, osc2.waveform, dt);

            const cut = osc2.filterCutoff + hardFilter + (modC2 * 5000);
            const res = Math.max(0, osc2.filterResonance + (modR2 * 10));
            sig = this.filters[1].process(sig, cut, res, this.sampleRate);

            voiceMix += sig * osc2.gain * this.envVals[1] * hardAmp * Math.max(0, 1.0 + modG2);
        }

        if (osc3.enabled && this.envVals[2] > 0.0001) {
            let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;
            const d = osc3.lfoDepth || 0;
            const v = this.lfoVals[2];
            if (osc3.lfoTarget === 'pitch') hardPitch = v * d;
            else if (osc3.lfoTarget === 'filter') hardFilter = v * d * 20;
            else if (osc3.lfoTarget === 'tremolo') hardAmp = 1.0 - (v * d * 0.005);

            let freq;
            if (osc3ModPitch) {
                const cents = osc3.coarseDetune + osc3.fineDetune + hardPitch + (modP3 * 1200);
                freq = this.baseFreq * globalBend * Math.pow(2, cents / 1200.0);
            } else {
                freq = osc3StaticFreq;
            }

            let sig = this.oscs[2].process(freq, osc3.waveform, dt);

            const cut = osc3.filterCutoff + hardFilter + (modC3 * 5000);
            const res = Math.max(0, osc3.filterResonance + (modR3 * 10));
            sig = this.filters[2].process(sig, cut, res, this.sampleRate);

            voiceMix += sig * osc3.gain * this.envVals[2] * hardAmp * Math.max(0, 1.0 + modG3);
        }

        panPhase += dt * panSpeed;
        if (panPhase > 1.0) panPhase -= 1.0;

        const autoPan = Math.sin(panPhase * TWO_PI) * panDepth;
        let p = this.panPos * spreadAmount;
        p += autoPan;
        p = Math.max(-1.0, Math.min(1.0, p));

        const gainL = 0.5 * (1.0 - p);
        const gainR = 0.5 * (1.0 + p);

        bufL[s] += voiceMix * gainL * voiceGain;
        bufR[s] += voiceMix * gainR * voiceGain;
    }
  }
}

// --- 4. PROCESSOR LOGIC ---

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.isOversamplingEnabled = true;
    this.globalBendMultiplier = 1.0; 

    const OVERSAMPLE = 2;
    const workingRate = sampleRate * OVERSAMPLE;

    this.voices = [];
    for(let i=0; i<64; i++) {
        const v = new Voice(workingRate);
        v.panPos = Math.sin(i * 123.456); 
        this.voices.push(v);
    }

    this.presets = {
        normal: DUMMY_PRESET_DATA,
        latch: DUMMY_PRESET_DATA,
        strum: DUMMY_PRESET_DATA
    };

    this.maxPolyphony = 32; 
    this.strumDuration = 0.5;

    this.xm1L = 0; this.ym1L = 0;
    this.xm1R = 0; this.ym1R = 0;

    this.panPhase = 0;
    this.mixBufferL = null;
    this.mixBufferR = null;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'update_preset') {
        const { mode, data } = msg;
        if (mode && this.presets[mode]) {
            this.presets[mode] = this.normalizePreset(data);
        }
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
         if (msg.strumDuration) this.strumDuration = msg.strumDuration;
         if (msg.enableOversampling !== undefined) this.isOversamplingEnabled = msg.enableOversampling;
         if (msg.globalBend !== undefined) this.globalBendMultiplier = msg.globalBend;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq, msg.voiceType, msg.mode);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          modMatrix: (data.modMatrix || []).map(row => ({
              ...row,
              amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
          })),
          gain: data.gain || 0.5,
          spread: data.spread || 0,
          stereoPanSpeed: data.stereoPanSpeed || 0,
          stereoPanDepth: data.stereoPanDepth || 0
      };
  }

  triggerVoice(id, freq, type, mode) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq, type, mode);
            return;
        }
    }

    let activeCount = 0;
    let oldestReleased = null;
    let oldestReleaseTime = Infinity;
    let oldestHeld = null;
    let oldestStartTime = Infinity;
    let freeVoice = null;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            activeCount++;
            if (v.releaseTime > 0) {
                if (v.releaseTime < oldestReleaseTime) {
                    oldestReleaseTime = v.releaseTime;
                    oldestReleased = v;
                }
            } else {
                if (v.startTime < oldestStartTime) {
                    oldestStartTime = v.startTime;
                    oldestHeld = v;
                }
            }
        } else {
            if (!freeVoice) freeVoice = v;
        }
    }

    if (activeCount < this.maxPolyphony && freeVoice) {
        freeVoice.trigger(id, freq, type, mode);
        return;
    }

    const victim = oldestReleased || oldestHeld || freeVoice || this.voices[0];
    if (victim) {
        if (victim.active && victim.id !== id) {
             this.port.postMessage({ type: 'voice_stolen', id: victim.id });
        }
        victim.trigger(id, freq, type, mode);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             this.voices[i].targetFreq = freq;
        }
    }
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];
    if (!channelL) return true;
    const len = channelL.length;

    const OVERSAMPLE = this.isOversamplingEnabled ? 2 : 1;
    const workingRate = sampleRate * OVERSAMPLE;
    const workingLen = len * OVERSAMPLE;
    const dt = 1.0 / workingRate;

    const startTime = globalThis.performance ? globalThis.performance.now() : 0;
    // Increased Budget to prevent premature dropouts
    const MAX_BUDGET_MS = 3.0; 

    if (!this.mixBufferL || this.mixBufferL.length !== workingLen) {
        this.mixBufferL = new Float32Array(workingLen);
        this.mixBufferR = new Float32Array(workingLen);
        this.voices.forEach(v => v.updateSampleRate(workingRate));
    }

    this.mixBufferL.fill(0);
    this.mixBufferR.fill(0);

    const masterPreset = this.presets.normal;
    const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0;
    const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0;
    const initialPanPhase = this.panPhase;

    let voicesProcessed = 0;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            if ((v.mode === 'trigger' || v.type === 'strum') && v.releaseTime === 0) {
                if (currentTime - v.startTime >= this.strumDuration) v.release();
            }

            const presetToUse = this.presets[v.type] || this.presets.normal;
            v.renderBlock(presetToUse, dt, this.mixBufferL, this.mixBufferR, workingLen, panSpeed, panDepth, initialPanPhase, this.globalBendMultiplier);
            voicesProcessed++;

            if (startTime > 0 && voicesProcessed % 2 === 0) {
                if (globalThis.performance.now() - startTime > MAX_BUDGET_MS) {
                    break;
                }
            }
        }
    }

    this.panPhase += (workingLen * dt * panSpeed);
    while (this.panPhase > 1.0) this.panPhase -= 1.0;

    if (OVERSAMPLE === 2) {
        for (let s = 0; s < len; s++) {
            const osIdx = s * 2;
            let sl1 = Math.tanh(this.mixBufferL[osIdx] * 0.8);
            let sr1 = Math.tanh(this.mixBufferR[osIdx] * 0.8);
            let sl2 = Math.tanh(this.mixBufferL[osIdx+1] * 0.8);
            let sr2 = Math.tanh(this.mixBufferR[osIdx+1] * 0.8);

            const outL = (sl1 + sl2) * 0.5;
            const outR = (sr1 + sr2) * 0.5;

            const yL = outL - this.xm1L + 0.995 * this.ym1L;
            this.xm1L = outL;
            this.ym1L = yL;

            const yR = outR - this.xm1R + 0.995 * this.ym1R;
            this.xm1R = outR;
            this.ym1R = yR;

            channelL[s] = yL;
            if (channelR) channelR[s] = yR;
        }
    } else {
        for (let s = 0; s < len; s++) {
            const sl = Math.tanh(this.mixBufferL[s] * 0.8);
            const sr = Math.tanh(this.mixBufferR[s] * 0.8);

            const yL = sl - this.xm1L + 0.995 * this.ym1L;
            this.xm1L = sl;
            this.ym1L = yL;

            const yR = sr - this.xm1R + 0.995 * this.ym1R;
            this.xm1R = sr;
            this.ym1R = yR;

            channelL[s] = yL;
            if (channelR) channelR[s] = yR;
        }
    }

    return true;
  }
}

registerProcessor('synth-processor', PrismaProcessor);
