  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { getRainbowPeriod, PITCH_SCALE } from './ProjectionService';

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, number[]>; // Map of nodeId to array of active modes
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    activeCursors: Map<number, any>;
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    dynamicSize: number;
    view: { x: number, y: number, w: number, h: number };
    time: number;
}

export class LatticeRenderer {
    private lastData: any = null;
    private lastSettingsSignature: string = '';
    private lastSize: number = 0;
    private lastScale: number = 0;
    private lastBrightenedLines: LatticeLine[] = [];

    public render(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, dynamicCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, visualLatchedNodes, activeLines, brightenedLines, activeCursors, cursorPositions, nodeTriggerHistory, globalBend, effectiveScale, dynamicSize, view, time } = state;
        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const staticCtx = staticCanvas.getContext('2d', { alpha: true });
        const activeCtx = dynamicCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !staticCtx || !activeCtx) return;
        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        let needsFullRedraw = false;
        if (bgCanvas.width !== dynamicSize * dpr || bgCanvas.height !== dynamicSize * dpr) {
            [bgCanvas, staticCanvas, dynamicCanvas].forEach(c => { c.width = dynamicSize * dpr; c.height = dynamicSize * dpr; });
            bgCtx.scale(dpr, dpr); staticCtx.scale(dpr, dpr); activeCtx.scale(dpr, dpr);
            needsFullRedraw = true;
        } else {
            bgCtx.setTransform(dpr, 0, 0, dpr, 0, 0); staticCtx.setTransform(dpr, 0, 0, dpr, 0, 0); activeCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }

        const sig = JSON.stringify({ spacing: settings.buttonSpacingScale, size: settings.buttonSizeScale, colors: settings.colors, layout: settings.layoutApproach, vis: settings.limitVisuals, shape: settings.buttonShape, text: settings.nodeTextSizeScale, fraction: settings.showFractionBar, width: settings.baseLineWidth, bright: settings.lineBrighteningWidth });
        const staticDirty = needsFullRedraw || data !== this.lastData || sig !== this.lastSettingsSignature || effectiveScale !== this.lastScale || dynamicSize !== this.lastSize;
        const bgDirty = staticDirty || brightenedLines !== this.lastBrightenedLines;

        if (staticDirty) { this.lastData = data; this.lastSettingsSignature = sig; this.lastScale = effectiveScale; this.lastSize = dynamicSize; }
        if (bgDirty) { this.lastBrightenedLines = brightenedLines; }

        const pixOff = -globalBend * (PITCH_SCALE / 12) * effectiveScale, pad = 300; 
        const leftB = view.x - pad, rightB = view.x + view.w + pad, topB = view.y - pad - pixOff, botB = view.y + view.h + pad - pixOff;
        const center = dynamicSize / 2, spacing = settings.buttonSpacingScale * effectiveScale, baseR = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isD = settings.buttonShape === ButtonShape.DIAMOND, colorC = settings.colors, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

        // --- BACKGROUND LINES ---
        if (bgDirty) {
            bgCtx.clearRect(0, 0, dynamicSize, dynamicSize); bgCtx.lineCap = 'round';
            const baseW = settings.baseLineWidth || 1.0, linesByL: Record<number, number[]> = {};
            for (const line of data.lines) { if (!linesByL[line.limit]) linesByL[line.limit] = []; linesByL[line.limit].push(line.x1 * spacing + center, line.y1 * spacing + center, line.x2 * spacing + center, line.y2 * spacing + center); }
            for (const lStr in linesByL) {
                const l = parseInt(lStr), coords = linesByL[l], color = isJI ? '#fff' : (colorC[l] || '#666');
                bgCtx.beginPath();
                for(let i=0; i<coords.length; i+=4) {
                    if (Math.max(coords[i], coords[i+2]) < 0 || Math.min(coords[i], coords[i+2]) > dynamicSize || Math.max(coords[i+1], coords[i+3]) < 0 || Math.min(coords[i+1], coords[i+3]) > dynamicSize) continue;
                    bgCtx.moveTo(coords[i], coords[i+1]); bgCtx.lineTo(coords[i+2], coords[i+3]);
                }
                bgCtx.lineWidth = (l === 1 ? Math.max(2.5, baseW * 2.5) : baseW) * effectiveScale; bgCtx.strokeStyle = color; bgCtx.globalAlpha = isJI ? 0.15 : 0.3;
                if (l === 1) bgCtx.setLineDash([5 * effectiveScale, 5 * effectiveScale]); else bgCtx.setLineDash([]);
                bgCtx.stroke();
            }
            bgCtx.setLineDash([]); 
            if (brightenedLines.length > 0) {
                const bW = settings.lineBrighteningWidth || 1.0;
                for (const line of brightenedLines) {
                    const x1 = line.x1 * spacing + center, y1 = line.y1 * spacing + center, x2 = line.x2 * spacing + center, y2 = line.y2 * spacing + center;
                    bgCtx.beginPath(); bgCtx.moveTo(x1, y1); bgCtx.lineTo(x2, y2);
                    bgCtx.lineWidth = bW * effectiveScale; bgCtx.strokeStyle = isJI ? '#fff' : (colorC[line.limit] || '#666'); bgCtx.globalAlpha = isJI ? 0.4 : 0.8; bgCtx.stroke();
                }
            }
        }

        // --- STATIC NODES ---
        if (staticDirty) {
            staticCtx.clearRect(0, 0, dynamicSize, dynamicSize);
            for (const node of data.nodes) {
                const x = node.x * spacing + center, y = node.y * spacing + center;
                const cT = isJI ? '#fff' : (colorC[node.limitTop] || '#666'), cB = isJI ? '#eee' : (colorC[node.limitBottom] || '#666');
                staticCtx.globalAlpha = 1.0; staticCtx.beginPath();
                if (isD) { staticCtx.moveTo(x, y - baseR); staticCtx.lineTo(x + baseR, y); staticCtx.lineTo(x, y + baseR); staticCtx.lineTo(x - baseR, y); } else { staticCtx.arc(x, y, baseR, 0, Math.PI * 2); }
                staticCtx.closePath();
                if (isJI) { staticCtx.fillStyle = '#111'; staticCtx.fill(); staticCtx.lineWidth = 2 * effectiveScale; staticCtx.strokeStyle = '#fff'; staticCtx.stroke(); }
                else { const g = staticCtx.createLinearGradient(x, y - baseR, x, y + baseR); g.addColorStop(0.45, cT); g.addColorStop(0.55, cB); staticCtx.fillStyle = g; staticCtx.fill(); }
                if (settings.buttonSizeScale > 0.4) {
                    staticCtx.fillStyle = isJI ? '#fff' : 'white'; staticCtx.textAlign = 'center'; staticCtx.textBaseline = 'middle';
                    let fS = Math.max(10, Math.min(18, 14 * settings.buttonSizeScale)) * settings.nodeTextSizeScale * effectiveScale;
                    staticCtx.font = `bold ${fS}px sans-serif`; 
                    const sY = settings.showFractionBar ? 0.55 : 0.50;
                    staticCtx.fillText(node.n.toString(), x, y - (baseR * sY));
                    if (settings.showFractionBar) {
                        staticCtx.beginPath(); staticCtx.moveTo(x - (baseR * 0.4), y); staticCtx.lineTo(x + (baseR * 0.4), y);
                        staticCtx.lineWidth = 1 * effectiveScale; staticCtx.strokeStyle = isJI ? 'rgba(255,255,255,0.4)' : `rgba(255,255,255,0.8)`; staticCtx.stroke();
                    }
                    staticCtx.fillText(node.d.toString(), x, y + (baseR * sY));
                }
            }
        }

        // --- DYNAMIC LAYER (Active Nodes & Cursors) ---
        activeCtx.clearRect(0, 0, dynamicSize, dynamicSize); activeCtx.lineCap = 'round';
        const aS = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33, rPh = (time * 0.001 * aS), fPh = settings.voiceLeadingReverseDir ? (1.0 - (rPh % 1.0)) : (rPh % 1.0);

        // Voice Leading Lines
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + center, y1 = line.y1 * spacing + center, x2 = line.x2 * spacing + center, y2 = line.y2 * spacing + center;
            if (Math.max(x1, x2) < leftB || Math.min(x1, x2) > rightB || Math.max(y1, y2) < topB || Math.min(y1, y2) > botB) continue;
            activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = (isJI ? 2 : 4) * effectiveScale; activeCtx.strokeStyle = isJI ? '#fff' : (colorC[line.limit] || '#666'); activeCtx.globalAlpha = 1.0; activeCtx.stroke();
            if (settings.isVoiceLeadingAnimationEnabled) {
                const g = activeCtx.createLinearGradient(x1, y1, x2, y2);
                g.addColorStop(0, 'rgba(255,255,255,0)'); g.addColorStop(Math.max(0, fPh-0.2), 'rgba(255,255,255,0)'); g.addColorStop(fPh, isJI ? 'rgba(255,255,255,1.0)' : 'rgba(255,255,255,0.7)'); g.addColorStop(Math.min(1, fPh+0.2), 'rgba(255,255,255,0)'); g.addColorStop(1, 'rgba(255,255,255,0)');
                activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2); activeCtx.strokeStyle = g; activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale; activeCtx.globalAlpha = 0.3; activeCtx.stroke();
                activeCtx.lineWidth = 4 * effectiveScale; activeCtx.globalAlpha = 1.0; activeCtx.stroke();
            }
        }

        // Active Nodes (Concentric Rings for Multi-Mode)
        // Modes: 1=Drone (Green), 2=Strings (Blue), 3=Plucked (Orange)
        for (const [id, modes] of visualLatchedNodes) {
             const node = data.nodes.find(n => n.id === id); if (!node) continue;
             const x = node.x * spacing + center, y = node.y * spacing + center;
             if (x < leftB || x > rightB || y < topB || y > botB) continue;

             const zoom = settings.latchedZoomScale;
             const rBase = baseR * zoom;

             // Draw Base Glow (White for JI, colored for others)
             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isD) { activeCtx.moveTo(x, y - rBase); activeCtx.lineTo(x + rBase, y); activeCtx.lineTo(x, y + rBase); activeCtx.lineTo(x - rBase, y); } 
             else { activeCtx.arc(x, y, rBase, 0, Math.PI * 2); }
             activeCtx.closePath();

             if (isJI) { 
                 activeCtx.fillStyle = '#fff'; 
             } else { 
                 const g = activeCtx.createLinearGradient(x, y-rBase, x, y+rBase); 
                 g.addColorStop(0.45, isJI ? '#fff' : (colorC[node.limitTop] || '#666')); 
                 g.addColorStop(0.55, colorC[node.limitBottom] || '#666'); 
                 activeCtx.fillStyle = g; 
             }
             activeCtx.fill();

             // Sort modes: Drone(1) -> Strings(2) -> Plucked(3)
             // We draw from outside in, so Drone is largest.
             const uniqueModes = Array.from(new Set(modes)).sort((a,b) => a - b);

             // Base Stroke logic
             if (settings.isColoredIlluminationEnabled && !isJI) {
                 const phase = (y % getRainbowPeriod(settings.buttonSpacingScale * effectiveScale)) / getRainbowPeriod(settings.buttonSpacingScale * effectiveScale);
                 activeCtx.strokeStyle = `hsl(${(settings.rainbowOffset + phase * 360) % 360}, ${settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100}%, 60%)`;
                 activeCtx.lineWidth = 4 * effectiveScale;
                 activeCtx.stroke();
             } else if (uniqueModes.length === 0) {
                 // Fallback for hover-only or default
                 activeCtx.strokeStyle = isJI ? '#fff' : 'white'; 
                 activeCtx.lineWidth = isJI ? 4 * effectiveScale : 3 * effectiveScale; 
                 if (isJI) { activeCtx.shadowBlur = 10 * effectiveScale; activeCtx.shadowColor = '#fff'; }
                 activeCtx.stroke(); 
                 activeCtx.shadowBlur = 0;
             }

             // Draw Concentric Mode Rings
             // Drone (1): Green, offset +6px
             // Strings (2): Blue, offset +2px
             // Plucked (3): Orange, inset -2px (inner halo)
             const ringWidth = 3 * effectiveScale;

             uniqueModes.forEach(mode => {
                 activeCtx.beginPath();
                 let r = rBase;
                 let color = 'white';

                 if (mode === 1) { // Drone
                     r = rBase + (6 * effectiveScale);
                     color = '#22c55e'; // Green-500
                 } else if (mode === 2) { // Strings
                     r = rBase + (2 * effectiveScale);
                     color = '#3b82f6'; // Blue-500
                 } else if (mode === 3) { // Plucked
                     r = rBase - (2 * effectiveScale);
                     color = '#f97316'; // Orange-500
                 }

                 if (isD) { 
                     activeCtx.moveTo(x, y - r); activeCtx.lineTo(x + r, y); activeCtx.lineTo(x, y + r); activeCtx.lineTo(x - r, y); activeCtx.lineTo(x, y - r);
                 } else { 
                     activeCtx.arc(x, y, r, 0, Math.PI * 2); 
                 }

                 activeCtx.lineWidth = ringWidth;
                 activeCtx.strokeStyle = color;
                 activeCtx.stroke();
             });

             // Text Label
             if (settings.buttonSizeScale * zoom > 0.4) {
                activeCtx.fillStyle = isJI ? '#000' : 'white'; activeCtx.textAlign = 'center'; activeCtx.textBaseline = 'middle';
                let fS = Math.max(12, Math.min(22, 16 * settings.buttonSizeScale * zoom)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fS}px sans-serif`; const sY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (rBase * sY));
                if (settings.showFractionBar) { activeCtx.beginPath(); activeCtx.moveTo(x - (rBase * 0.4), y); activeCtx.lineTo(x + (rBase * 0.4), y); activeCtx.lineWidth = 1 * effectiveScale; activeCtx.strokeStyle = isJI ? 'rgba(0,0,0,0.5)' : 'white'; activeCtx.stroke(); }
                activeCtx.fillText(node.d.toString(), x, y + (rBase * sY));
             }
        }

        // Ripple Effects
        const now = Date.now(), ripD = 500; activeCtx.lineWidth = 2 * effectiveScale; activeCtx.strokeStyle = 'white';
        nodeTriggerHistory.forEach((ts, id) => {
            const age = now - ts; if (age > ripD) return;
            const n = data.nodes.find(node => node.id === id); if (!n) return;
            const x = n.x * spacing + center, y = n.y * spacing + center;
            if (x < leftB || x > rightB || y < topB || y > botB) return;
            const prog = age / ripD, ripR = baseR * (1 + (1 - Math.pow(1 - prog, 3)) * 1.5);
            activeCtx.beginPath(); activeCtx.arc(x, y, ripR, 0, Math.PI * 2); activeCtx.globalAlpha = 1.0 - prog; activeCtx.stroke();
        });
        activeCtx.globalAlpha = 1.0;

        // Pitch Bend Lines
        if (settings.isPitchBendEnabled) {
            activeCursors.forEach(c => {
                if (c.originNodeId) {
                    const n = data.nodes.find(node => node.id === c.originNodeId);
                    if (n) {
                         const pos = cursorPositions.get(c.pointerId);
                         if (pos) { activeCtx.beginPath(); activeCtx.moveTo(n.x * spacing + center, n.y * spacing + center); activeCtx.lineTo(pos.x, pos.y); activeCtx.strokeStyle = isJI ? '#fff' : 'white'; activeCtx.lineWidth = 2 * effectiveScale; activeCtx.globalAlpha = 0.5; activeCtx.stroke(); activeCtx.globalAlpha = 1.0; }
                    }
                }
            });
        }
    }
}

import React, { useState, useEffect } from 'react';
import { AppSettings, KeyMappings } from '../../types';

interface Props {
    settings: AppSettings;
    updateSettings: (s: Partial<AppSettings>) => void;
}

const BehaviorTab: React.FC<Props> = ({ settings, updateSettings }) => {
    const [listeningFor, setListeningFor] = useState<keyof KeyMappings | null>(null);

    const handleChange = (key: keyof AppSettings, value: any) => updateSettings({ [key]: value });

    useEffect(() => {
        const handleBinderKeyDown = (e: KeyboardEvent) => {
            if (!listeningFor) return;
            e.preventDefault(); 
            e.stopPropagation();
            let key = e.key.toLowerCase(); 
            if (key === ' ') key = 'Space';
            updateSettings({ keyMappings: { ...settings.keyMappings, [listeningFor]: key } });
            setListeningFor(null);
        };
        if (listeningFor) window.addEventListener('keydown', handleBinderKeyDown);
        return () => window.removeEventListener('keydown', handleBinderKeyDown);
    }, [listeningFor, settings, updateSettings]);

    const renderKeyBinding = (label: string, actionKey: keyof KeyMappings) => {
        const isListening = listeningFor === actionKey;
        const currentKey = settings.keyMappings[actionKey].toUpperCase();
        return (
            <div className="flex justify-between items-center bg-slate-800 p-2 rounded border border-slate-700 hover:border-slate-600 transition-colors">
                <span className="text-sm font-bold text-slate-300">{label}</span>
                <button onClick={() => setListeningFor(actionKey)} className={`px-3 py-1 text-xs font-mono font-bold rounded min-w-[80px] border transition-all ${isListening ? 'bg-red-900 border-red-500 text-white animate-pulse' : 'bg-slate-700 border-slate-600 text-blue-300 hover:bg-slate-600'}`}>
                    {isListening ? 'Press Key...' : currentKey}
                </button>
            </div>
        );
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">

                {/* SUSTAIN & LATCHING SECTION */}
                <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Sustain & Latching</h3>
                <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-4">
                    <div>
                        <label className="block text-sm font-semibold text-slate-300 mb-2">Latch Stack Logic</label>
                        <div className="flex gap-2">
                            <button onClick={() => handleChange('latchLogic', 'fifo')} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.latchLogic === 'fifo' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                FIFO (Remove First)
                            </button>
                            <button onClick={() => handleChange('latchLogic', 'lifo')} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.latchLogic === 'lifo' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                LIFO (Remove Last)
                            </button>
                        </div>
                        <p className="text-[9px] text-slate-500 italic mt-2">Determines which active patch layer is removed first when tapping a multi-latched node.</p>
                    </div>

                    <label className="flex items-center justify-between cursor-pointer">
                        <div className="space-y-1">
                            <span className="text-sm font-semibold text-white">Always Retrigger Chords</span>
                            <p className="text-[9px] text-slate-500">If enabled, selecting a chord will always re-attack notes, even if already sustained.</p>
                        </div>
                        <input type="checkbox" checked={settings.chordsAlwaysRelatch} onChange={(e) => handleChange('chordsAlwaysRelatch', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500" />
                    </label>
                </div>

                <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1 mt-6">Audio Performance</h3>

                <label className="flex items-center justify-between cursor-pointer bg-slate-900/40 p-3 rounded border border-slate-700/50">
                    <div className="space-y-1">
                        <span className="text-sm font-semibold text-white">High Quality Oversampling</span>
                        <p className="text-[10px] text-slate-500">Enable 2x Oversampling. Disable to reduce CPU usage.</p>
                    </div>
                    <input type="checkbox" checked={settings.enableOversampling} onChange={(e) => handleChange('enableOversampling', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500" />
                </label>

                <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-4">
                    <div>
                        <label className="block text-sm font-semibold text-slate-300 mb-2">Wavetable Fidelity</label>
                        <div className="flex gap-2">
                            {[2048, 8192, 65536].map(size => (
                                <button key={size} onClick={() => handleChange('wavetableSize', size)} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.wavetableSize === size ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                    {size === 2048 ? 'Low (2K)' : size === 8192 ? 'Med (8K)' : 'HiFi (64K)'}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-semibold text-slate-300 mb-2">Interpolation</label>
                        <div className="flex gap-2">
                            <button onClick={() => handleChange('interpolationType', 'linear')} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.interpolationType === 'linear' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                Linear
                            </button>
                            <button onClick={() => handleChange('interpolationType', 'cubic')} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.interpolationType === 'cubic' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                Cubic (Smooth)
                            </button>
                        </div>
                        <p className="text-[9px] text-slate-500 italic mt-2">Cubic removes grit for deep FM synthesis but uses slightly more CPU.</p>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                    <label className="block text-sm font-semibold text-slate-300">Audio Latency Mode</label>
                    <div className="flex gap-2">
                        {['interactive', 'balanced', 'playback'].map(mode => (
                            <button key={mode} onClick={() => handleChange('audioLatencyHint', mode)} className={`flex-1 py-2 text-xs font-bold rounded border capitalize ${settings.audioLatencyHint === mode ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>
                                {mode === 'interactive' ? 'Low (Fast)' : mode === 'playback' ? 'High (Stable)' : mode}
                            </button>
                        ))}
                    </div>
                    <p className="text-[10px] text-slate-500 italic">Lower latency is better for performance but may cause clicks on weaker devices.</p>
                </div>

                <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                    <label className="block text-sm font-semibold text-slate-300">Max Polyphony</label>
                    <div className="flex items-center gap-3">
                        <input 
                            type="range" 
                            min="1" 
                            max="64" 
                            step="1" 
                            value={settings.polyphony} 
                            onChange={(e) => handleChange('polyphony', parseInt(e.target.value))} 
                            className="flex-grow h-2 bg-indigo-900 rounded-lg appearance-none cursor-pointer accent-indigo-500" 
                        />
                        <span className="text-xs font-mono font-bold w-8 text-right text-indigo-300">{settings.polyphony}</span>
                    </div>
                    <p className="text-[10px] text-slate-500 italic">Limits simultaneous voices. Lower this if audio crackles.</p>
                </div>

                <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1 mt-6">Interaction</h3>
                <div className="space-y-4">
                  <label className="flex items-center justify-between cursor-pointer">
                    <span className="text-sm font-semibold">Enable Keyboard Shortcuts</span>
                    <input type="checkbox" checked={settings.enableKeyboardShortcuts} onChange={(e) => handleChange('enableKeyboardShortcuts', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500" />
                  </label>
                  <div className="space-y-2">
                    <label className="block text-sm font-semibold">Strum Duration</label>
                    <div className="flex items-center gap-3">
                      <input type="range" min="0.1" max="2.0" step="0.1" value={settings.strumDuration} onChange={(e) => handleChange('strumDuration', parseFloat(e.target.value))} className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
                      <span className="text-xs font-mono w-10">{settings.strumDuration.toFixed(1)}s</span>
                    </div>
                  </div>
                </div>

                <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1 mt-6">Recording</h3>
                <div className="space-y-4">
                  <label className="flex items-center justify-between cursor-pointer">
                    <div className="space-y-1">
                        <span className="text-sm font-semibold text-white">Record screen activity</span>
                        <p className="text-[10px] text-slate-500">Include visual capture when recording audio.</p>
                    </div>
                    <input type="checkbox" checked={settings.recordScreenActivity} onChange={(e) => handleChange('recordScreenActivity', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500" />
                  </label>
                </div>
              </div>

              <div className="space-y-6">
                <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Key Bindings</h3>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-2">
                  <div className="text-[10px] font-bold text-slate-500 uppercase mt-2">Modes & Patch</div>
                  {renderKeyBinding('Drone Mode', 'modeDrone')}
                  {renderKeyBinding('Strings Mode', 'modeStrings')}
                  {renderKeyBinding('Plucked Mode', 'modePlucked')}
                  {renderKeyBinding('Toggle Synth', 'synth')}

                  <div className="text-[10px] font-bold text-slate-500 uppercase mt-2">Expression</div>
                  {renderKeyBinding('Sustain', 'sustain')}
                  {renderKeyBinding('Pitch Bend', 'bend')}

                  <div className="text-[10px] font-bold text-slate-500 uppercase mt-2">Global</div>
                  {renderKeyBinding('BPM Up', 'bpmUp')}
                  {renderKeyBinding('BPM Down', 'bpmDown')}
                  {renderKeyBinding('Add Chord', 'addChord')}
                  {renderKeyBinding('Center View', 'center')}

                  <div className="text-[10px] font-bold text-slate-500 uppercase mt-2">Arpeggiator</div>
                  {renderKeyBinding('Toggle Seq', 'toggleSequencer')}
                  {renderKeyBinding('Play All', 'playAllArps')}
                  {renderKeyBinding('Stop All', 'stopAllArps')}

                  <div className="text-[10px] font-bold text-slate-500 uppercase mt-2">System</div>
                  {renderKeyBinding('All Notes Off', 'off')}
                  {renderKeyBinding('Panic', 'panic')}
                  {renderKeyBinding('Open Settings', 'settings')}
                  {renderKeyBinding('Volume Up', 'volumeUp')}
                  {renderKeyBinding('Volume Down', 'volumeDown')}
                </div>
              </div>
            </div>
        </div>
    );
};

export default BehaviorTab;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          handleClearNode(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // Right click via pointer event type (secondary button)
      if (e.button === 2) {
          if (hitNode) handleClearNode(hitNode.id);
          return;
      }

      if (hitNode) {
        // Start Long Press Timer
        longPressTimerRef.current = {
            id: window.setTimeout(() => {
                handleClearNode(hitNode.id);
                // Also cancel the active cursor interaction for this press
                const cursor = activeCursorsRef.current.get(e.pointerId);
                if (cursor) {
                    // Release the voice immediately if it started
                    const vId = `cursor-${e.pointerId}-${hitNode.id}`;
                    audioEngine.stopVoice(vId);
                    if (settings.midiEnabled) midiService.noteOff(vId);
                }
                longPressTimerRef.current = null;
            }, LONG_PRESS_MS),
            nodeId: hitNode.id,
            pointerId: e.pointerId
        };

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        const isSustainingInstrument = latchMode === 1 || latchMode === 2, isSustainActive = isCurrentSustainEnabled, isBendEnabled = settings.isPitchBendEnabled;
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     const newStack = [...stack];
                     if (settings.latchLogic === 'lifo') {
                         newStack.pop(); 
                     } else {
                         newStack.shift();
                     }

                     if (newStack.length === 0) next.delete(hitNode.id);
                     else next.set(hitNode.id, newStack);
                 }
                 return next;
             });
        }
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);
            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { getRainbowPeriod, PITCH_SCALE } from './ProjectionService';

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, number[]>; // Map of nodeId to array of active modes
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    activeCursors: Map<number, any>;
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    nodeClearHistory?: Map<string, number>; // Added for implosions
    globalBend: number;
    effectiveScale: number;
    dynamicSize: number;
    view: { x: number, y: number, w: number, h: number };
    time: number;
}

export class LatticeRenderer {
    private lastData: any = null;
    private lastSettingsSignature: string = '';
    private lastSize: number = 0;
    private lastScale: number = 0;
    private lastBrightenedLines: LatticeLine[] = [];

    public render(bgCanvas: HTMLCanvasElement, staticCanvas: HTMLCanvasElement, dynamicCanvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, visualLatchedNodes, activeLines, brightenedLines, activeCursors, cursorPositions, nodeTriggerHistory, nodeClearHistory, globalBend, effectiveScale, dynamicSize, view, time } = state;
        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const staticCtx = staticCanvas.getContext('2d', { alpha: true });
        const activeCtx = dynamicCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !staticCtx || !activeCtx) return;
        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        let needsFullRedraw = false;
        if (bgCanvas.width !== dynamicSize * dpr || bgCanvas.height !== dynamicSize * dpr) {
            [bgCanvas, staticCanvas, dynamicCanvas].forEach(c => { c.width = dynamicSize * dpr; c.height = dynamicSize * dpr; });
            bgCtx.scale(dpr, dpr); staticCtx.scale(dpr, dpr); activeCtx.scale(dpr, dpr);
            needsFullRedraw = true;
        } else {
            bgCtx.setTransform(dpr, 0, 0, dpr, 0, 0); staticCtx.setTransform(dpr, 0, 0, dpr, 0, 0); activeCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }

        const sig = JSON.stringify({ spacing: settings.buttonSpacingScale, size: settings.buttonSizeScale, colors: settings.colors, layout: settings.layoutApproach, vis: settings.limitVisuals, shape: settings.buttonShape, text: settings.nodeTextSizeScale, fraction: settings.showFractionBar, width: settings.baseLineWidth, bright: settings.lineBrighteningWidth });
        const staticDirty = needsFullRedraw || data !== this.lastData || sig !== this.lastSettingsSignature || effectiveScale !== this.lastScale || dynamicSize !== this.lastSize;
        const bgDirty = staticDirty || brightenedLines !== this.lastBrightenedLines;

        if (staticDirty) { this.lastData = data; this.lastSettingsSignature = sig; this.lastScale = effectiveScale; this.lastSize = dynamicSize; }
        if (bgDirty) { this.lastBrightenedLines = brightenedLines; }

        const pixOff = -globalBend * (PITCH_SCALE / 12) * effectiveScale, pad = 300; 
        const leftB = view.x - pad, rightB = view.x + view.w + pad, topB = view.y - pad - pixOff, botB = view.y + view.h + pad - pixOff;
        const center = dynamicSize / 2, spacing = settings.buttonSpacingScale * effectiveScale, baseR = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isD = settings.buttonShape === ButtonShape.DIAMOND, colorC = settings.colors, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

        // --- BACKGROUND LINES ---
        if (bgDirty) {
            bgCtx.clearRect(0, 0, dynamicSize, dynamicSize); bgCtx.lineCap = 'round';
            const baseW = settings.baseLineWidth || 1.0, linesByL: Record<number, number[]> = {};
            for (const line of data.lines) { if (!linesByL[line.limit]) linesByL[line.limit] = []; linesByL[line.limit].push(line.x1 * spacing + center, line.y1 * spacing + center, line.x2 * spacing + center, line.y2 * spacing + center); }
            for (const lStr in linesByL) {
                const l = parseInt(lStr), coords = linesByL[l], color = isJI ? '#fff' : (colorC[l] || '#666');
                bgCtx.beginPath();
                for(let i=0; i<coords.length; i+=4) {
                    if (Math.max(coords[i], coords[i+2]) < 0 || Math.min(coords[i], coords[i+2]) > dynamicSize || Math.max(coords[i+1], coords[i+3]) < 0 || Math.min(coords[i+1], coords[i+3]) > dynamicSize) continue;
                    bgCtx.moveTo(coords[i], coords[i+1]); bgCtx.lineTo(coords[i+2], coords[i+3]);
                }
                bgCtx.lineWidth = (l === 1 ? Math.max(2.5, baseW * 2.5) : baseW) * effectiveScale; bgCtx.strokeStyle = color; bgCtx.globalAlpha = isJI ? 0.15 : 0.3;
                if (l === 1) bgCtx.setLineDash([5 * effectiveScale, 5 * effectiveScale]); else bgCtx.setLineDash([]);
                bgCtx.stroke();
            }
            bgCtx.setLineDash([]); 
            if (brightenedLines.length > 0) {
                const bW = settings.lineBrighteningWidth || 1.0;
                for (const line of brightenedLines) {
                    const x1 = line.x1 * spacing + center, y1 = line.y1 * spacing + center, x2 = line.x2 * spacing + center, y2 = line.y2 * spacing + center;
                    bgCtx.beginPath(); bgCtx.moveTo(x1, y1); bgCtx.lineTo(x2, y2);
                    bgCtx.lineWidth = bW * effectiveScale; bgCtx.strokeStyle = isJI ? '#fff' : (colorC[line.limit] || '#666'); bgCtx.globalAlpha = isJI ? 0.4 : 0.8; bgCtx.stroke();
                }
            }
        }

        // --- STATIC NODES ---
        if (staticDirty) {
            staticCtx.clearRect(0, 0, dynamicSize, dynamicSize);
            for (const node of data.nodes) {
                const x = node.x * spacing + center, y = node.y * spacing + center;
                const cT = isJI ? '#fff' : (colorC[node.limitTop] || '#666'), cB = isJI ? '#eee' : (colorC[node.limitBottom] || '#666');
                staticCtx.globalAlpha = 1.0; staticCtx.beginPath();
                if (isD) { staticCtx.moveTo(x, y - baseR); staticCtx.lineTo(x + baseR, y); staticCtx.lineTo(x, y + baseR); staticCtx.lineTo(x - baseR, y); } else { staticCtx.arc(x, y, baseR, 0, Math.PI * 2); }
                staticCtx.closePath();
                if (isJI) { staticCtx.fillStyle = '#111'; staticCtx.fill(); staticCtx.lineWidth = 2 * effectiveScale; staticCtx.strokeStyle = '#fff'; staticCtx.stroke(); }
                else { const g = staticCtx.createLinearGradient(x, y - baseR, x, y + baseR); g.addColorStop(0.45, cT); g.addColorStop(0.55, cB); staticCtx.fillStyle = g; staticCtx.fill(); }
                if (settings.buttonSizeScale > 0.4) {
                    staticCtx.fillStyle = isJI ? '#fff' : 'white'; staticCtx.textAlign = 'center'; staticCtx.textBaseline = 'middle';
                    let fS = Math.max(10, Math.min(18, 14 * settings.buttonSizeScale)) * settings.nodeTextSizeScale * effectiveScale;
                    staticCtx.font = `bold ${fS}px sans-serif`; 
                    const sY = settings.showFractionBar ? 0.55 : 0.50;
                    staticCtx.fillText(node.n.toString(), x, y - (baseR * sY));
                    if (settings.showFractionBar) {
                        staticCtx.beginPath(); staticCtx.moveTo(x - (baseR * 0.4), y); staticCtx.lineTo(x + (baseR * 0.4), y);
                        staticCtx.lineWidth = 1 * effectiveScale; staticCtx.strokeStyle = isJI ? 'rgba(255,255,255,0.4)' : `rgba(255,255,255,0.8)`; staticCtx.stroke();
                    }
                    staticCtx.fillText(node.d.toString(), x, y + (baseR * sY));
                }
            }
        }

        // --- DYNAMIC LAYER (Active Nodes & Cursors) ---
        activeCtx.clearRect(0, 0, dynamicSize, dynamicSize); activeCtx.lineCap = 'round';
        const aS = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33, rPh = (time * 0.001 * aS), fPh = settings.voiceLeadingReverseDir ? (1.0 - (rPh % 1.0)) : (rPh % 1.0);

        // Voice Leading Lines
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + center, y1 = line.y1 * spacing + center, x2 = line.x2 * spacing + center, y2 = line.y2 * spacing + center;
            if (Math.max(x1, x2) < leftB || Math.min(x1, x2) > rightB || Math.max(y1, y2) < topB || Math.min(y1, y2) > botB) continue;
            activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = (isJI ? 2 : 4) * effectiveScale; activeCtx.strokeStyle = isJI ? '#fff' : (colorC[line.limit] || '#666'); activeCtx.globalAlpha = 1.0; activeCtx.stroke();
            if (settings.isVoiceLeadingAnimationEnabled) {
                const g = activeCtx.createLinearGradient(x1, y1, x2, y2);
                g.addColorStop(0, 'rgba(255,255,255,0)'); g.addColorStop(Math.max(0, fPh-0.2), 'rgba(255,255,255,0)'); g.addColorStop(fPh, isJI ? 'rgba(255,255,255,1.0)' : 'rgba(255,255,255,0.7)'); g.addColorStop(Math.min(1, fPh+0.2), 'rgba(255,255,255,0)'); g.addColorStop(1, 'rgba(255,255,255,0)');
                activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2); activeCtx.strokeStyle = g; activeCtx.lineWidth = 10 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale; activeCtx.globalAlpha = 0.3; activeCtx.stroke();
                activeCtx.lineWidth = 4 * effectiveScale; activeCtx.globalAlpha = 1.0; activeCtx.stroke();
            }
        }

        // Active Nodes (Concentric Rings for Multi-Mode)
        for (const [id, modes] of visualLatchedNodes) {
             const node = data.nodes.find(n => n.id === id); if (!node) continue;
             const x = node.x * spacing + center, y = node.y * spacing + center;
             if (x < leftB || x > rightB || y < topB || y > botB) continue;

             const zoom = settings.latchedZoomScale;
             const rBase = baseR * zoom;

             // Draw Base Glow (White for JI, colored for others)
             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isD) { activeCtx.moveTo(x, y - rBase); activeCtx.lineTo(x + rBase, y); activeCtx.lineTo(x, y + rBase); activeCtx.lineTo(x - rBase, y); } 
             else { activeCtx.arc(x, y, rBase, 0, Math.PI * 2); }
             activeCtx.closePath();

             if (isJI) { 
                 activeCtx.fillStyle = '#fff'; 
             } else { 
                 const g = activeCtx.createLinearGradient(x, y-rBase, x, y+rBase); 
                 g.addColorStop(0.45, isJI ? '#fff' : (colorC[node.limitTop] || '#666')); 
                 g.addColorStop(0.55, colorC[node.limitBottom] || '#666'); 
                 activeCtx.fillStyle = g; 
             }
             activeCtx.fill();

             // Sort modes: Drone(1) -> Strings(2) -> Plucked(3)
             // We draw from outside in, so Drone is largest.
             const uniqueModes = Array.from(new Set(modes)).sort((a,b) => a - b);

             // Base Stroke logic
             if (settings.isColoredIlluminationEnabled && !isJI) {
                 const phase = (y % getRainbowPeriod(settings.buttonSpacingScale * effectiveScale)) / getRainbowPeriod(settings.buttonSpacingScale * effectiveScale);
                 activeCtx.strokeStyle = `hsl(${(settings.rainbowOffset + phase * 360) % 360}, ${settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100}%, 60%)`;
                 activeCtx.lineWidth = 4 * effectiveScale;
                 activeCtx.stroke();
             } else if (uniqueModes.length === 0) {
                 // Fallback for hover-only or default
                 activeCtx.strokeStyle = isJI ? '#fff' : 'white'; 
                 activeCtx.lineWidth = isJI ? 4 * effectiveScale : 3 * effectiveScale; 
                 if (isJI) { activeCtx.shadowBlur = 10 * effectiveScale; activeCtx.shadowColor = '#fff'; }
                 activeCtx.stroke(); 
                 activeCtx.shadowBlur = 0;
             }

             // Draw Concentric Mode Rings
             const ringWidth = 3 * effectiveScale;
             uniqueModes.forEach(mode => {
                 activeCtx.beginPath();
                 let r = rBase;
                 let color = 'white';
                 if (mode === 1) { r = rBase + (6 * effectiveScale); color = '#22c55e'; }
                 else if (mode === 2) { r = rBase + (2 * effectiveScale); color = '#3b82f6'; }
                 else if (mode === 3) { r = rBase - (2 * effectiveScale); color = '#f97316'; }

                 if (isD) { 
                     activeCtx.moveTo(x, y - r); activeCtx.lineTo(x + r, y); activeCtx.lineTo(x, y + r); activeCtx.lineTo(x - r, y); activeCtx.lineTo(x, y - r);
                 } else { 
                     activeCtx.arc(x, y, r, 0, Math.PI * 2); 
                 }
                 activeCtx.lineWidth = ringWidth; activeCtx.strokeStyle = color; activeCtx.stroke();
             });

             // Text Label
             if (settings.buttonSizeScale * zoom > 0.4) {
                activeCtx.fillStyle = isJI ? '#000' : 'white'; activeCtx.textAlign = 'center'; activeCtx.textBaseline = 'middle';
                let fS = Math.max(12, Math.min(22, 16 * settings.buttonSizeScale * zoom)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fS}px sans-serif`; const sY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (rBase * sY));
                if (settings.showFractionBar) { activeCtx.beginPath(); activeCtx.moveTo(x - (rBase * 0.4), y); activeCtx.lineTo(x + (rBase * 0.4), y); activeCtx.lineWidth = 1 * effectiveScale; activeCtx.strokeStyle = isJI ? 'rgba(0,0,0,0.5)' : 'white'; activeCtx.stroke(); }
                activeCtx.fillText(node.d.toString(), x, y + (rBase * sY));
             }
        }

        // Ripple Effects (Explosions)
        const now = Date.now(), ripD = 500; activeCtx.lineWidth = 2 * effectiveScale; activeCtx.strokeStyle = 'white';
        nodeTriggerHistory.forEach((ts, id) => {
            const age = now - ts; if (age > ripD) return;
            const n = data.nodes.find(node => node.id === id); if (!n) return;
            const x = n.x * spacing + center, y = n.y * spacing + center;
            if (x < leftB || x > rightB || y < topB || y > botB) return;
            const prog = age / ripD, ripR = baseR * (1 + (1 - Math.pow(1 - prog, 3)) * 1.5);
            activeCtx.beginPath(); activeCtx.arc(x, y, ripR, 0, Math.PI * 2); activeCtx.globalAlpha = 1.0 - prog; activeCtx.stroke();
        });

        // Implosion Effects (Clearing)
        if (nodeClearHistory) {
            nodeClearHistory.forEach((ts, id) => {
                const age = now - ts; if (age > 300) return; // Faster than explosion
                const n = data.nodes.find(node => node.id === id); if (!n) return;
                const x = n.x * spacing + center, y = n.y * spacing + center;
                const prog = age / 300;
                const ripR = baseR * (2.5 * (1.0 - prog)); // Shrink from large to node

                activeCtx.beginPath(); 
                activeCtx.arc(x, y, Math.max(0, ripR), 0, Math.PI * 2); 
                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = 'white'; 
                activeCtx.globalAlpha = 1.0 - prog; 
                activeCtx.stroke();
            });
        }

        activeCtx.globalAlpha = 1.0;

        // Pitch Bend Lines
        if (settings.isPitchBendEnabled) {
            activeCursors.forEach(c => {
                if (c.originNodeId) {
                    const n = data.nodes.find(node => node.id === c.originNodeId);
                    if (n) {
                         const pos = cursorPositions.get(c.pointerId);
                         if (pos) { activeCtx.beginPath(); activeCtx.moveTo(n.x * spacing + center, n.y * spacing + center); activeCtx.lineTo(pos.x, pos.y); activeCtx.strokeStyle = isJI ? '#fff' : 'white'; activeCtx.lineWidth = 2 * effectiveScale; activeCtx.globalAlpha = 0.5; activeCtx.stroke(); activeCtx.globalAlpha = 1.0; }
                    }
                }
            });
        }
    }
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          handleClearNode(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // Right click via pointer event type (secondary button)
      if (e.button === 2) {
          if (hitNode) handleClearNode(hitNode.id);
          return;
      }

      if (hitNode) {
        // Start Long Press Timer
        longPressTimerRef.current = {
            id: window.setTimeout(() => {
                handleClearNode(hitNode.id);
                // Also cancel the active cursor interaction for this press
                const cursor = activeCursorsRef.current.get(e.pointerId);
                if (cursor) {
                    // Release the voice immediately if it started
                    const vId = `cursor-${e.pointerId}-${hitNode.id}`;
                    audioEngine.stopVoice(vId);
                    if (settings.midiEnabled) midiService.noteOff(vId);
                }
                longPressTimerRef.current = null;
            }, LONG_PRESS_MS),
            nodeId: hitNode.id,
            pointerId: e.pointerId
        };

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        const isSustainingInstrument = latchMode === 1 || latchMode === 2, isSustainActive = isCurrentSustainEnabled, isBendEnabled = settings.isPitchBendEnabled;
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     // Add if not present
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     // If present, behavior depends on Mode
                     if (latchMode === 1) { 
                         // MODE 1 (Drone): Toggle OFF behavior
                         const newStack = stack.filter(m => m !== latchMode);
                         if (newStack.length === 0) next.delete(hitNode.id);
                         else next.set(hitNode.id, newStack);
                     } else {
                         // MODE 2 (Strings/Sustain): RE-TRIGGER behavior (Do not remove)
                         // We manually restart the voice here because the useEffect latch watcher won't see a change
                         const { preset } = getVoiceParams(latchMode, settings.isStrumEnabled);
                         const vid = `node-${hitNode.id}-${latchMode}`;
                         // Force stop then start to ensure envelope re-attack
                         audioEngine.stopVoice(vid);
                         audioEngine.startVoice(vid, hitNode.ratio, settings.baseFrequency, preset, 'latch');
                         if (settings.midiEnabled) {
                             midiService.noteOff(vid);
                             midiService.noteOn(vid, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                         }
                         // No change to persistentLatches needed, so we return 'prev' to avoid re-renders of the map
                         return prev; 
                     }
                 }
                 return next;
             });
        }
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);
            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleDeactivateStep = (nodeId: string) => {
      setPersistentLatches(prev => {
          const next = new Map(prev);
          const stack = next.get(nodeId);
          if (!stack || stack.length === 0) return prev;

          let modeToRemove = -1;
          let newStack: number[] = [];

          if (settings.latchLogic === 'lifo') {
              // Remove Last
              modeToRemove = stack[stack.length - 1];
              newStack = stack.slice(0, -1);
          } else {
              // Remove First (FIFO)
              modeToRemove = stack[0];
              newStack = stack.slice(1);
          }

          // Force stop the audio for this specific mode
          const vId = `node-${nodeId}-${modeToRemove}`;
          audioEngine.stopVoice(vId);
          if (settings.midiEnabled) midiService.noteOff(vId);

          if (newStack.length === 0) {
              next.delete(nodeId);
              // Trigger visual implosion for full clear
              nodeClearHistory.current.set(nodeId, Date.now());
          } else {
              next.set(nodeId, newStack);
          }

          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          // Right click now calls progressive deactivation
          handleDeactivateStep(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // RIGHT CLICK (Button 2) -> Progressive Deactivation
      if (e.button === 2) {
          if (hitNode) handleDeactivateStep(hitNode.id);
          return;
      }

      if (hitNode) {
        // Start Long Press Timer (Still clears ALL for safety/accessibility)
        longPressTimerRef.current = {
            id: window.setTimeout(() => {
                handleClearNode(hitNode.id);
                // Also cancel the active cursor interaction for this press
                const cursor = activeCursorsRef.current.get(e.pointerId);
                if (cursor) {
                    const vId = `cursor-${e.pointerId}-${hitNode.id}`;
                    audioEngine.stopVoice(vId);
                    if (settings.midiEnabled) midiService.noteOff(vId);
                }
                longPressTimerRef.current = null;
            }, LONG_PRESS_MS),
            nodeId: hitNode.id,
            pointerId: e.pointerId
        };

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

        const isSustainingInstrument = latchMode === 1 || latchMode === 2, isSustainActive = isCurrentSustainEnabled, isBendEnabled = settings.isPitchBendEnabled;

        // LEFT CLICK LOGIC: Activation / Adding
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     // Add if not present
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     // If present, RE-TRIGGER behavior (Do not remove)
                     // Manually restart voice to re-attack
                     const { preset } = getVoiceParams(latchMode, settings.isStrumEnabled);
                     const vid = `node-${hitNode.id}-${latchMode}`;
                     audioEngine.stopVoice(vid);
                     audioEngine.startVoice(vid, hitNode.ratio, settings.baseFrequency, preset, 'latch');
                     if (settings.midiEnabled) {
                         midiService.noteOff(vid);
                         midiService.noteOn(vid, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                     }
                     return prev; 
                 }
                 return next;
             });
        }
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);
            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

const handleDeactivateStep = (nodeId: string) => {
    setPersistentLatches(prev => {
        const next = new Map<string, number[]>(prev);
        const stack = next.get(nodeId);
        if (!stack || stack.length === 0) return prev;

        let modeToRemove = -1;
        let newStack: number[] = [];

        if (settings.latchLogic === 'lifo') {
            // Remove Last
            modeToRemove = stack[stack.length - 1];
            newStack = stack.slice(0, -1);
        } else {
            // Remove First (FIFO)
            modeToRemove = stack[0];
            newStack = stack.slice(1);
        }

        // Force stop the audio for this specific mode
        const vId = `node-${nodeId}-${modeToRemove}`;
        audioEngine.stopVoice(vId);
        if (settings.midiEnabled) midiService.noteOff(vId);

        if (newStack.length === 0) {
            next.delete(nodeId);
            // Trigger visual implosion for full clear
            nodeClearHistory.current.set(nodeId, Date.now());
        } else {
            next.set(nodeId, newStack);
        }

        return next;
    });
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleDeactivateStep = (nodeId: string) => {
      setPersistentLatches(prev => {
          const next = new Map<string, number[]>(prev);
          const stack = next.get(nodeId);
          if (!stack || stack.length === 0) return prev;

          let modeToRemove = -1;
          let newStack: number[] = [];

          if (settings.latchLogic === 'lifo') {
              // Remove Last
              modeToRemove = stack[stack.length - 1];
              newStack = stack.slice(0, -1);
          } else {
              // Remove First (FIFO)
              modeToRemove = stack[0];
              newStack = stack.slice(1);
          }

          // Force stop the audio for this specific mode
          const vId = `node-${nodeId}-${modeToRemove}`;
          audioEngine.stopVoice(vId);
          if (settings.midiEnabled) midiService.noteOff(vId);

          if (newStack.length === 0) {
              next.delete(nodeId);
              // Trigger visual implosion for full clear
              nodeClearHistory.current.set(nodeId, Date.now());
          } else {
              next.set(nodeId, newStack);
          }

          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          // Right click now calls progressive deactivation
          handleDeactivateStep(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // RIGHT CLICK (Button 2) -> Progressive Deactivation
      if (e.button === 2) {
          if (hitNode) handleDeactivateStep(hitNode.id);
          return;
      }

      if (hitNode) {
        // Start Long Press Timer (Still clears ALL for safety/accessibility)
        longPressTimerRef.current = {
            id: window.setTimeout(() => {
                handleClearNode(hitNode.id);
                // Also cancel the active cursor interaction for this press
                const cursor = activeCursorsRef.current.get(e.pointerId);
                if (cursor) {
                    const vId = `cursor-${e.pointerId}-${hitNode.id}`;
                    audioEngine.stopVoice(vId);
                    if (settings.midiEnabled) midiService.noteOff(vId);
                }
                longPressTimerRef.current = null;
            }, LONG_PRESS_MS),
            nodeId: hitNode.id,
            pointerId: e.pointerId
        };

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

        const isSustainingInstrument = latchMode === 1 || latchMode === 2, isSustainActive = isCurrentSustainEnabled, isBendEnabled = settings.isPitchBendEnabled;

        // LEFT CLICK LOGIC: Activation / Adding
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     // Add if not present
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     // If present, RE-TRIGGER behavior (Do not remove)
                     // Manually restart voice to re-attack
                     const { preset } = getVoiceParams(latchMode, settings.isStrumEnabled);
                     const vid = `node-${hitNode.id}-${latchMode}`;
                     audioEngine.stopVoice(vid);
                     audioEngine.startVoice(vid, hitNode.ratio, settings.baseFrequency, preset, 'latch');
                     if (settings.midiEnabled) {
                         midiService.noteOff(vid);
                         midiService.noteOn(vid, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                     }
                     return prev; 
                 }
                 return next;
             });
        }
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);
            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleDeactivateStep = (nodeId: string) => {
      setPersistentLatches(prev => {
          const next = new Map<string, number[]>(prev);
          const stack = next.get(nodeId);
          if (!stack || stack.length === 0) return prev;

          let modeToRemove = -1;
          let newStack: number[] = [];

          if (settings.latchLogic === 'lifo') {
              // Remove Last
              modeToRemove = stack[stack.length - 1];
              newStack = stack.slice(0, -1);
          } else {
              // Remove First (FIFO)
              modeToRemove = stack[0];
              newStack = stack.slice(1);
          }

          // Force stop the audio for this specific mode
          const vId = `node-${nodeId}-${modeToRemove}`;
          audioEngine.stopVoice(vId);
          if (settings.midiEnabled) midiService.noteOff(vId);

          if (newStack.length === 0) {
              next.delete(nodeId);
              // Trigger visual implosion for full clear
              nodeClearHistory.current.set(nodeId, Date.now());
          } else {
              next.set(nodeId, newStack);
          }

          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          // Right click now calls progressive deactivation
          handleDeactivateStep(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // RIGHT CLICK (Button 2) -> Progressive Deactivation
      if (e.button === 2) {
          if (hitNode) handleDeactivateStep(hitNode.id);
          return;
      }

      if (hitNode) {
        const isSustainingInstrument = latchMode === 1 || latchMode === 2;
        const isSustainActive = isCurrentSustainEnabled;
        const isAlreadyLatched = persistentLatches.has(hitNode.id);

        // Only start long press timer if ALREADY latched.
        // This prevents the "Hold to play -> Accidental Clear" bug in Mode 2.
        if (isAlreadyLatched) {
            longPressTimerRef.current = {
                id: window.setTimeout(() => {
                    handleClearNode(hitNode.id);
                    // Also clear visual cursor hover to prevent stuck enlargement
                    setActiveCursors(prev => { 
                        const next = new Map(prev);
                        const c = next.get(e.pointerId);
                        if(c) next.set(e.pointerId, { ...c, hoverNodeId: null, originNodeId: null });
                        return next;
                    });
                    if (activeCursorsRef.current.has(e.pointerId)) {
                        activeCursorsRef.current.get(e.pointerId)!.hoverNodeId = null;
                    }
                    longPressTimerRef.current = null;
                }, LONG_PRESS_MS),
                nodeId: hitNode.id,
                pointerId: e.pointerId
            };
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

        const isBendEnabled = settings.isPitchBendEnabled;

        // LEFT CLICK LOGIC
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     // Add if not present (Play)
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     // If present
                     if (latchMode === 1) { 
                         // MODE 1 (Drone): Toggle OFF behavior
                         const newStack = stack.filter(m => m !== latchMode);
                         if (newStack.length === 0) next.delete(hitNode.id);
                         else next.set(hitNode.id, newStack);
                     } else {
                         // MODE 2 (Strings/Sustain): Re-trigger DISABLED to avoid artifacts.
                         // Just act as a "Hold" or "No-Op" if tapping an active note.
                         // Long press (timer above) handles clearing.
                     }
                 }
                 return next;
             });
        }

        // Start Cursor / Gate Voice (only if not latched or latch mode 0)
        // If latch is active, the persistent logic above handled audio start.
        // Except for Pitch Bend interaction which needs a cursor.
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);

            // Only start gate voice if NOT sustaining/latching this specific press
            if (!isSustainActive) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null; 
}

const GRID_CELL_SIZE = 100; 
const LONG_PRESS_MS = 600;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRectRef = useRef<DOMRect | null>(null);
  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * effectiveScale;
      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, effectiveScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  // persistentLatches: Map<nodeId, array of active modes in order of activation>
  const [persistentLatches, setPersistentLatches] = useState<Map<string, number[]>>(new Map());
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());
  const nodeClearHistory = useRef<Map<string, number>>(new Map()); // For implosion animation

  // Long Press Refs
  const longPressTimerRef = useRef<{ id: number, nodeId: string, pointerId: number } | null>(null);

  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((stack) => stack.forEach(m => modes.add(m)));
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              // ID format: node-${nodeId}-${mode}
              const parts = voiceId.split('-');
              if (parts.length >= 3) {
                  const nodeId = parts[1];
                  const mode = parseInt(parts[2]);
                  setPersistentLatches(prev => {
                      if (prev.has(nodeId)) {
                          const next = new Map<string, number[]>(prev);
                          const existingStack = next.get(nodeId);
                          if (existingStack) {
                              const stack = existingStack.filter(m => m !== mode);
                              if (stack.length === 0) next.delete(nodeId);
                              else next.set(nodeId, stack);
                          }
                          return next;
                      }
                      return prev;
                  });
              }
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => { globalBendRef.current = semitones; });
      return unsubscribe;
  }, []);

  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      audioEngine.registerPreset(`chord-${id}-${mode}`, preset);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  const audioLatchedNodes = useMemo(() => {
      // Map<nodeId + mode, { nodeId, mode, presetId }>
      const effective = new Map<string, { nodeId: string, mode: number, presetId: string }>();

      persistentLatches.forEach((modes, nodeId) => {
          modes.forEach(mode => {
              const pId = mode === 2 ? 'normal' : 'latch';
              effective.set(`${nodeId}-${mode}`, { nodeId, mode, presetId: pId });
          });
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`;
                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        presetId = `chord-${chordId}-${n.voiceMode}`;
                    } else if (chordDef.soundConfig) {
                        presetId = `chord-${chordId}`;
                    } else {
                        presetId = n.voiceMode;
                    }
                } else if (chordDef.soundConfig) {
                    presetId = `chord-${chordId}`;
                } else {
                    presetId = (latchMode === 2) ? 'normal' : 'latch';
                }
                const key = `${n.id}-${mode}`;
                if (!effective.has(key)) effective.set(key, { nodeId: n.id, mode, presetId });
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  const visualLatchedNodes = useMemo(() => {
      // For visual rings, we just need unique nodeId -> list of modes
      const visual = new Map<string, number[]>();

      // Add all audio latched
      audioLatchedNodes.forEach((val) => {
          if (!visual.has(val.nodeId)) visual.set(val.nodeId, []);
          if (!visual.get(val.nodeId)!.includes(val.mode)) visual.get(val.nodeId)!.push(val.mode);
      });

      // Add temporary hovers
      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode === 1 || latchMode === 2;
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          if (isSustainingInstrument && isSustainActive && isBendEnabled) return;
          const isMelodic = !isSustainingInstrument || !isSustainActive || isBendEnabled;
          if (isMelodic && cursor.hoverNodeId) {
              if (!visual.has(cursor.hoverNodeId)) visual.set(cursor.hoverNodeId, []);
              if (!visual.get(cursor.hoverNodeId)!.includes(latchMode)) visual.get(cursor.hoverNodeId)!.push(latchMode);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, latchMode, isCurrentSustainEnabled]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of data.lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i], B = activeNodes[j];
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) { dist += Math.abs(A.coords[k] - B.coords[k]); }
                dist += Math.abs(A.octave - B.octave); 
                if (dist <= 2) {
                    active.push({ id: `${A.id}-${B.id}`, x1: A.x, y1: A.y, x2: B.x, y2: B.y, limit: Math.max(A.maxPrime, B.maxPrime), sourceId: A.id, targetId: B.id });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicSizeRef = useRef(dynamicSize);
  const effectiveScaleRef = useRef(effectiveScale);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => { if (dynamicCanvasRef.current) canvasRectRef.current = dynamicCanvasRef.current.getBoundingClientRect(); };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.addEventListener('scroll', updateRect);
      };
  }, []);

  useEffect(() => { updateRect(); }, [dynamicSize]);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches(prev => {
                const next = new Map<string, number[]>();
                prev.forEach((stack, key) => {
                    const nextStack = stack.filter(m => m !== mode);
                    if (nextStack.length > 0) next.set(key, nextStack);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: prev.limitDepths[limit as 3|5|7|11|13|15] + 1 } }));
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => ({ ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, prev.limitDepths[limit as 3|5|7|11|13|15] - 1) } }));
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((stack, id) => {
            const n = nodeMap.get(id);
            if (n) stack.forEach(mode => result.push({ node: n, mode }));
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2, viewportW = scrollContainerRef.current.clientWidth, viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => { if (isInitialLoad && !isGenerating && data.nodes.length > 0) { centerScroll(); setIsInitialLoad(false); } }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff; container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container || isInitialLoad) return;
      const oldScale = prevEffectiveScaleRef.current, newScale = effectiveScale;
      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth, viewH = container.clientHeight, centerOffset = dynamicSizeRef.current / 2;
          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale, newSpacing = settingsRef.current.buttonSpacingScale * newScale;
          const curX = container.scrollLeft, curY = container.scrollTop;
          const center_x = (curX + viewW / 2) - centerOffset, center_y = (curY + viewH / 2) - centerOffset;
          if (Math.abs(center_x) < 2.0 && Math.abs(center_y) < 2.0) {
              container.scrollLeft = centerOffset - viewW / 2; container.scrollTop = centerOffset - viewH / 2;
          } else {
              const nx = (center_x / oldSpacing) * newSpacing, ny = (center_y / oldSpacing) * newSpacing;
              container.scrollLeft = (nx + centerOffset) - viewW / 2; container.scrollTop = (ny + centerOffset) - viewH / 2;
          }
          requestAnimationFrame(updateRect);
      }
      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale, isInitialLoad]);

  const generationDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem, layout: settings.layoutApproach, depths: settings.limitDepths, complexities: settings.limitComplexities, hidden: settings.hiddenLimits, ratio: settings.latticeAspectRatio, skin: settings.activeSkin
  }), [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const eff: AppSettings = JSON.parse(JSON.stringify(settings));
        (eff.hiddenLimits || []).forEach((limit: number) => { if (eff.limitDepths[limit as 3|5|7|11|13|15] !== undefined) eff.limitDepths[limit as 3|5|7|11|13|15] = 0; });
        const result = generateLattice(eff);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => !eff.hiddenLimits.includes(l.limit) && visibleNodeIds.has(l.sourceId) && visibleNodeIds.has(l.targetId));
        let maxExtent = 0;
        result.nodes.forEach(n => { maxExtent = Math.max(maxExtent, Math.abs(n.x), Math.abs(n.y)); });
        const spacing = settingsRef.current.buttonSpacingScale * effectiveScale; 
        const clampedSize = Math.min((maxExtent * spacing * 2) + 600, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Sync Audio Latches with stack-aware Voice IDs
  const prevAudioLatchedRef = useRef<Map<string, { nodeId: string, mode: number, presetId: string }>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes, prev = prevAudioLatchedRef.current, nodes = nodeMap;
      current.forEach((data, key) => {
          if (!prev.has(key)) {
               const node = nodes.get(data.nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, data.presetId, 'latch');
                   if (settings.midiEnabled) midiService.noteOn(`node-${data.nodeId}-${data.mode}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((data, key) => {
          if (!current.has(key)) {
              audioEngine.stopVoice(`node-${data.nodeId}-${data.mode}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${data.nodeId}-${data.mode}`);
          }
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      let rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
      const bend = globalBendRef.current, pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
      const x = clientX - rect.left, y = clientY - (rect.top + pixelOffset); 
      const centerOffset = dynamicSizeRef.current / 2, spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
      const col = Math.floor(x / GRID_CELL_SIZE), row = Math.floor(y / GRID_CELL_SIZE);
      const cells = [`${col},${row}`, `${col+1},${row}`, `${col-1},${row}`, `${col},${row+1}`, `${col},${row-1}`, `${col+1},${row+1}`, `${col-1},${row-1}`, `${col+1},${row-1}`, `${col-1},${row+1}`];
      const grid = spatialGridRef.current, latchedMap = visualLatchedRef.current, zoom = settingsRef.current.latchedZoomScale;
      for(const key of cells) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset, ny = node.y * spacing + centerOffset;
                  const activeRadius = baseRadius * (latchedMap.has(node.id) ? zoom : 1.0);
                  if (x < nx - activeRadius || x > nx + activeRadius || y < ny - activeRadius || y > ny + activeRadius) continue;
                  const dx = x - nx, dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: 'trigger' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handleClearNode = (nodeId: string) => {
      nodeClearHistory.current.set(nodeId, Date.now());
      setPersistentLatches(prev => {
          const next = new Map(prev);
          next.delete(nodeId);
          return next;
      });
  };

  const handleDeactivateStep = (nodeId: string) => {
      setPersistentLatches(prev => {
          const next = new Map<string, number[]>(prev);
          const stack = next.get(nodeId);
          if (!stack || stack.length === 0) return prev;

          let modeToRemove = -1;
          let newStack: number[] = [];

          if (settings.latchLogic === 'lifo') {
              // Remove Last
              modeToRemove = stack[stack.length - 1];
              newStack = stack.slice(0, -1);
          } else {
              // Remove First (FIFO)
              modeToRemove = stack[0];
              newStack = stack.slice(1);
          }

          // Force stop the audio for this specific mode
          const vId = `node-${nodeId}-${modeToRemove}`;
          audioEngine.stopVoice(vId);
          if (settings.midiEnabled) midiService.noteOff(vId);

          if (newStack.length === 0) {
              next.delete(nodeId);
              // Trigger visual implosion for full clear
              nodeClearHistory.current.set(nodeId, Date.now());
          } else {
              next.set(nodeId, newStack);
          }

          return next;
      });
  };

  const handleContextMenu = (e: React.PointerEvent | React.MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      const hitNode = getHitNode(e.clientX, e.clientY);
      if (hitNode) {
          // Right click now calls progressive deactivation
          handleDeactivateStep(hitNode.id);
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault(); (e.target as HTMLElement).setPointerCapture(e.pointerId);
      updateRect();
      let canvasPos = { x: e.clientX, y: e.clientY };
      if (scrollContainerRef.current) {
          const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
          canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
      }
      cursorPositionsRef.current.set(e.pointerId, canvasPos);
      const hitNode = getHitNode(e.clientX, e.clientY), nodeId = hitNode ? hitNode.id : null;

      // RIGHT CLICK (Button 2) -> Progressive Deactivation
      if (e.button === 2) {
          if (hitNode) handleDeactivateStep(hitNode.id);
          return;
      }

      if (hitNode) {
        const isSustainingInstrument = latchMode === 1 || latchMode === 2;
        const isSustainActive = isCurrentSustainEnabled;
        const isAlreadyLatched = persistentLatches.has(hitNode.id);

        // Only start long press timer if ALREADY latched.
        // This prevents the "Hold to play -> Accidental Clear" bug in Mode 2.
        if (isAlreadyLatched) {
            longPressTimerRef.current = {
                id: window.setTimeout(() => {
                    handleClearNode(hitNode.id);
                    // Also clear visual cursor hover to prevent stuck enlargement
                    setActiveCursors(prev => { 
                        const next = new Map(prev);
                        const c = next.get(e.pointerId);
                        if(c) next.set(e.pointerId, { ...(c as ActiveCursor), hoverNodeId: null, originNodeId: null });
                        return next;
                    });
                    if (activeCursorsRef.current.has(e.pointerId)) {
                        activeCursorsRef.current.get(e.pointerId)!.hoverNodeId = null;
                    }
                    longPressTimerRef.current = null;
                }, LONG_PRESS_MS),
                nodeId: hitNode.id,
                pointerId: e.pointerId
            };
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;
        if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

        const isBendEnabled = settings.isPitchBendEnabled;

        // LEFT CLICK LOGIC
        if (isSustainingInstrument && isSustainActive) {
             setPersistentLatches(prev => {
                 const next = new Map<string, number[]>(prev);
                 const stack = next.get(hitNode.id) || [];

                 if (!stack.includes(latchMode)) {
                     // Add if not present (Play)
                     next.set(hitNode.id, [...stack, latchMode]);
                 } else {
                     // If present
                     if (latchMode === 1) { 
                         // MODE 1 (Drone): Toggle OFF behavior
                         const newStack = stack.filter(m => m !== latchMode);
                         if (newStack.length === 0) next.delete(hitNode.id);
                         else next.set(hitNode.id, newStack);
                     } else {
                         // MODE 2 (Strings/Sustain): Re-trigger DISABLED to avoid artifacts.
                         // Just act as a "Hold" or "No-Op" if tapping an active note.
                         // Long press (timer above) handles clearing.
                     }
                 }
                 return next;
             });
        }

        // Start Cursor / Gate Voice (only if not latched or latch mode 0)
        // If latch is active, the persistent logic above handled audio start.
        // Except for Pitch Bend interaction which needs a cursor.
        if (isBendEnabled || !isSustainActive || latchMode === 3) {
            const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false, interactionLockedNodeId: null };
            setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
            activeCursorsRef.current.set(e.pointerId, newCursor);

            // Only start gate voice if NOT sustaining/latching this specific press
            if (!isSustainActive) {
                const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
                audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, preset, playback);
                if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
            }
        }
      } else {
          const newCursor: ActiveCursor = { pointerId: e.pointerId, originNodeId: null, hoverNodeId: null, hasMoved: false, interactionLockedNodeId: null };
          setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, newCursor); return next; });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // Cancel Long Press on Move
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    let canvasPos = { x: e.clientX, y: e.clientY };
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect(), bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale;
        canvasPos = { x: (e.clientX - r.left) + scrollContainerRef.current.scrollLeft, y: (e.clientY - r.top) + scrollContainerRef.current.scrollTop - pix };
    }
    const prevPos = cursorPositionsRef.current.get(e.pointerId); cursorPositionsRef.current.set(e.pointerId, canvasPos);
    let hasMoved = cursor.hasMoved;
    if (!hasMoved && prevPos) { if (Math.abs(canvasPos.x - prevPos.x) > 2 || Math.abs(canvasPos.y - prevPos.y) > 2) hasMoved = true; }
    const hitNode = getHitNode(e.clientX, e.clientY), hitId = hitNode ? hitNode.id : null;
    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
    const isBendEnabled = settingsRef.current.isPitchBendEnabled, isBending = isBendEnabled && !!cursor.originNodeId;
    if (isBending && dynamicCanvasRef.current) {
         const centerOffset = dynamicSizeRef.current / 2, rect = canvasRectRef.current || dynamicCanvasRef.current.getBoundingClientRect();
         const bend = globalBendRef.current, pix = -bend * (PITCH_SCALE / 12) * effectiveScale; 
         const originNode = nodeMapRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originY = (rect.top + pix) + (originNode.y * spacing) + centerOffset;
             const bentRatio = getPitchRatioFromScreenDelta(e.clientY - originY, spacing);
             audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}-${cursor.originNodeId}`, originNode.ratio * bentRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }
    if (cursor.hoverNodeId !== hitId) {
        if (!isBending && cursor.hoverNodeId && playback === 'gate') {
             audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
             if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        if (hitNode && !isBending) {
             const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
             audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
             if (settingsRef.current.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
        }
        const updated: ActiveCursor = { ...cursor, hoverNodeId: hitId, hasMoved: hasMoved };
        activeCursorsRef.current.set(e.pointerId, updated);
        setActiveCursors(prev => { const next = new Map(prev); next.set(e.pointerId, updated); return next; });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Cancel Long Press
    if (longPressTimerRef.current && longPressTimerRef.current.pointerId === e.pointerId) {
        clearTimeout(longPressTimerRef.current.id);
        longPressTimerRef.current = null;
    }

    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
        if (cursor.originNodeId && settingsRef.current.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.originNodeId}`);
        } else if (cursor.hoverNodeId && playback === 'gate') {
            audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
            if (settingsRef.current.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
        }
        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current); nextRef.delete(e.pointerId); activeCursorsRef.current = nextRef;
        setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
    }
  };

  const render = (time: number) => {
      const bg = bgLineCanvasRef.current, st = staticCanvasRef.current, ac = dynamicCanvasRef.current, wr = wrapperRef.current, sc = scrollContainerRef.current;
      const currentScale = effectiveScaleRef.current; 
      if (wr) { wr.style.transform = `translate3d(0px, ${-globalBendRef.current * (PITCH_SCALE / 12) * currentScale}px, 0px)`; }
      if (!bg || !st || !ac || !sc) { animationFrameRef.current = requestAnimationFrame(render); return; }
      rendererRef.current.render(bg, st, ac, {
          data: dataRef.current, settings: settingsRef.current, visualLatchedNodes: visualLatchedRef.current, activeLines: activeLinesRef.current, brightenedLines: brightenedLinesRef.current, activeCursors: activeCursorsRef.current, cursorPositions: cursorPositionsRef.current, nodeTriggerHistory: nodeTriggerHistory.current, globalBend: globalBendRef.current, effectiveScale: effectiveScaleRef.current, dynamicSize: dynamicSizeRef.current, view: { x: sc.scrollLeft, y: sc.scrollTop, w: sc.clientWidth, h: sc.clientHeight }, time,
          // Extra render state for implosions
          // @ts-ignore - Extending the renderer state dynamically if needed or just passing it
          nodeClearHistory: nodeClearHistory.current 
      });
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode, offset = settings.backgroundYOffset || 0, isJI = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';
      const base: React.CSSProperties = { minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize, pointerEvents: uiUnlocked ? 'none' : 'auto', backgroundPosition: `center calc(50% + ${offset}px)`, backgroundRepeat: 'no-repeat', backgroundSize: 'cover' };
      if (isJI) return { ...base, backgroundColor: 'black', backgroundImage: 'none' };
      switch(mode) {
          case 'rainbow':
              const p = getRainbowPeriod(settings.buttonSpacingScale * effectiveScale), stops = [];
              for(let i=0; i<=6; i++) { stops.push(`hsl(${settings.rainbowOffset + i*60}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${(i/6)*100}%`); }
              return { ...base, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${p}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...base, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...base, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...base, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...base, backgroundColor: '#002200' };
          case 'slate_grey': return { ...base, backgroundColor: '#334155' };
          case 'image': return settings.backgroundImageData ? { ...base, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain' } : { ...base, backgroundColor: 'black' };
          default: return { ...base, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp} onContextMenu={handleContextMenu}>
        <div ref={wrapperRef} className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
